void solve(int len){
	ll now = 0;
	for(int i = 0; i < len - 1; ++ i){
		int left = 0, right = 9, ans = -1;
		while(left <= right){
			int mid = left + right >> 1;
			if(ask(now * 10 + mid)){
				ans = mid;
				left = mid + 1;
			}
			else{
				right = mid - 1;
			}
		}
		assert(ans != -1);
		now = now * 10 + ans;
	}

	int left = len == 1, right = 9, ans = -1;
	while(left <= right){
		int mid = left + right >> 1;
		if(ask((now * 10 + mid) * 10)){
			ans = mid;
			right = mid - 1;
		}
		else{
			left = mid + 1;
		}
	}
	assert(ans != -1);
	now = now * 10 + ans;
	answer(now);
}

