struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   bool test(long n, long q) {
      bool res = false;
      if( q <= n and std::to_string(q) <= std::to_string(n) ) res = true;
      if( q >  n and std::to_string(q) >  std::to_string(n) ) res = true;
      long t = res ? 1 : 0;
      // dumplll(n, q, t);
      return res;
   }
   bool query(long q) {
      printf("? %ld\n", q);
      fflush(stdout);
      std::string str;
      std::cin >> str;
      if( str[0] == 'Y' ) return true;
      return false;
   }
   void solve() {
      long x; scan(x);
      long base = 100000000;
      long addtail = 1000000000;
      // long res = (1LL << 32) - 1;
      std::string cmp = "000000000009";
      for(long i = 0; i < 10; ++i) {
         long tt = 0;
         for(long k = 3; k >= 0; --k) {
            long ttt = tt + (1LL << k);
            if( ttt >= 10 ) { continue; }
            cmp[i] = ttt + '0';
            if( not test(x, std::stol(cmp)) ) tt = ttt;
         }
         cmp[i] = tt + '0';
      }
      cmp.pop_back();
      long res = std::stol(cmp) + 10;
      // dumpl(res);
      if( res == 0 ) {
         res = 1;
         long t = 2;
         for(long i = 0; i < 10; ++i) {
            // dumpl(t);
            bool b = test(x, t);
            // puts(test(x, t) ? "Yes" : "No");
            if( b ) {
               for(long k = 0; k < i; ++k) {
                  res *= 10;
               }
               break;
            }
            t *= 10;
         }
         printf("%ld\n", res);
      }
      else {
         while( res % 10 == 0 ) res /= 10;
         // printf("%ld\n", res);
         long t = 1;
         for(long i = 0; i < 10; ++i) {
            // dumpl(t);
            bool b = test(x, t);
            // puts(test(x, t) ? "Yes" : "No");
            if( not b ) {
               long len = i - (long)std::to_string(res).size();
               for(long k = 0; k < len; ++k) {
                  res *= 10;
               }
               break;
            }
            t *= 10;
         }
         printf("%ld\n", res);
      }
   }
};

