            if (n == 0) {
                aout(ans*10+x);
                return 0;
            } else if (x == 9) {
                ans = ans * 10 + x;
                n--;
                nl = true;
            } else if (visit[x+1] && !yn[x+1]) {
                ans = ans * 10 + x;
                n--;
                nl = true;
            } else {
                x += d;
            }
        } else {
            if (n == 0) {
                x++;
            } else if (visit[x-1] && yn[x-1]) {
                ans = ans * 10 + x-1;
                n--;
                nl = true;
            } else {
                x -= d;
            }
        }

        d /= 2; if (d == 0) d = 1;
        i++;
    }

    return 0;
}

