void get() {
    ll lo = 1e10, hi = (1e11)-1; 
    while (lo < hi) {
        ll mid = (lo+hi)/2;

        // find first which gives yes
        if (query(mid)) hi = mid;
        else lo = mid+1;
    }

    while (lo % 10 == 0) lo /= 10;
    ll p = 1;
    while (10*p <= lo) p *= 10;

    ll lo1 = 0, hi1 = 9;

    while (p*po10(hi1) > 1e18) hi1--;

    while (lo1 < hi1) {
        if (lo != 1) {
            ll mid = (lo1+hi1+1)/2;
            if (query(p*po10(mid))) lo1 = mid;
            else hi1 = mid-1;
        } else {
            ll mid = (lo1+hi1)/2;
            if (query((10*p-1)*po10(mid))) hi1 = mid;
            else lo1 = mid+1;
        }
    }

    cout << "! " << lo*po10(lo1) << endl;
}

