string get10(int len) {
  string res = "1";
  for (int i = 1; i < len; i ++)
    res.push_back('0');
  return res;
}

string get9(int len) {
  string res = "";
  for (int i = 0; i < len; i ++)
    res.push_back('9');
  return res;
}

int getlen() {
  int l = 1, r = 9;
  while (l < r) {
    int md = l + r >> 1;
    string s = get10(md + 1);
    printf("? %s\n", s.c_str());
    fflush(stdout);
    char foo[5];
    scanf("%s", foo);
    if (foo[0] == 'Y')
      l = md + 1;
    else
      r = md;
  }
  return l;
}

int getlen2(int r) {
  int l = 1;
  while (l < r) {
    int md = l + r >> 1;
    string s = get9(md);
    printf("? %s\n", s.c_str());
    fflush(stdout);
    char foo[5];
    scanf("%s", foo);
    if (foo[0] == 'Y')
      r = md;
    else
      l = md + 1;
  }
}

void work() {
  for (int i = 0; i < n; i ++) {
    int l = 0 + (i == 0), r = 9;
    while (l < r) {
      int md = l + r >> 1;
      ans[i] = md + '0';
      printf("? %s\n", ans.c_str());
      fflush(stdout);
      char foo[5];
      scanf("%s", foo);
      if (foo[0] == 'N')
        l = md + 1;
      else
        r = md;
    }
    ans[i] = l + '0';
    if (l == 9) {
      printf("? %s\n", ans.c_str());
      fflush(stdout);
      char foo[5];
      scanf("%s", foo);
      if (foo[0] == 'Y')
        ans[i] --;
    } else
      ans[i] --;
  }
}

int main() {
  int R = getlen();
  ans = get10(n = getlen2(R));
  ans.push_back('0');
  work();
  ans.pop_back();
  ans.back() ++;
  printf("! %s\n", ans.c_str());
  return 0;
}

