const LL MAXN = 1e9;
const int TIMES = 64;

struct Querier {
	LL chosen;
	void choose() {
		srand(time(NULL));
		chosen = rand() % MAXN;
		chosen++;
		cerr << "Chosen: " << chosen << endl;
	}
	bool ask(LL n) {
		bool res = false;
		if(n <= chosen && to_string(n) <= to_string(chosen)) res = true;
		if(n > chosen && to_string(n) > to_string(chosen)) res = true;
		cerr << "Asking " << n << " and answered = " << "NY"[res] << endl;
		return res;
	}
} qq;

LL conv(string s) {
	LL res = 0;
	for(auto &c: s) {
		res = res * 10 + (c - '0');
	}
	return res;
}

int main() {
  ios_base::sync_with_stdio(false);
	int asked = 0;
	qq.choose();
	auto ask = [&](LL n) -> bool {
		asked++;
		assert(asked < TIMES);
		char resp;
		bool ans;
#ifdef LOCAL
		ans = qq.ask(n);
#else
		cout << "? " << n << endl;
		cin >> resp;
		ans = resp == 'Y';
#endif
		return ans;
	};
	LL temp = 1;
	int idx = -1;
	for(int i = 1; i <= 10; i++) {
		if(ask(temp) == false) {
			idx = i;
			break;
		}
		temp *= 10;
	}
	string res;
	if(idx == -1) { // Power of 10
		if(ask(conv("9")) == true) {
			res = "1";
		} else {
			res = "19";
			for(int i = 1; ; i++) {
				assert(res.size() < 12);
				if(ask(conv(res)) == true) {
					break;
				} else {
					res.push_back('9');
				}
			}
			for(auto &c: res) {
				if(c == '9') c = '0';
			}
		}
	} else {
		assert(idx > 1);
		LL numdgts = idx - 1;
		res.resize(numdgts + 1);
		for(auto &c: res) {
			c = '9';
		}
		for(int i = 0; i < numdgts; i++) {
			int lower = i == 0, upper = 10, mid;
			while(lower < upper) {
				mid = (lower + upper) / 2;
				res[i] = mid + '0';
				if(ask(conv(res)) == false) {
					lower = mid + 1;
				} else {
					upper = mid;
				}
			}
			assert(lower != 10);
			res[i] = lower + '0';
		}
		res.pop_back();
	}
	cout << res << endl;
#ifdef LOCAL
	if(qq.chosen != conv(res)) {
		cerr << "WA!" << endl;
		assert(false);
	}
	cerr <<"AC!" << endl;
#endif
  return 0;
}

