char s[2];
void query(int x) { printf("? %d\n",x); fflush(stdout); scanf("%s",s); }

void work(int bit) {
	if(bit == 10) {
		puts("! 1000000000");
		return;
	}
	int ans = 0;
	int mpos, l, r, mid;
	for(int i = 1; i < bit; ++i) {
		mpos = 0, l = 0, r = 9;	
		while(l <= r) {
			mid = l + r >> 1;
			query(ans * 10 + mid);
			if(s[0] == 'Y') {
				if(mpos < mid) mpos = mid;
				l = mid + 1;
			} else {
				r = mid - 1;
			}
		}
		ans = ans * 10 + mpos;
	}
	mpos = 9, l = 0, r = 9;
	while(l <= r) {
		mid = l + r >> 1;
		query((ans * 10 + mid) * 10);
		if(s[0] == 'Y') {
			if(mpos > mid) mpos = mid;
			r = mid - 1;
		} else {
			l = mid + 1;
		}
	}
	ans = ans * 10 + mpos;
	printf("! %d\n", ans);
	return;
}

int main() {
	for(int cur = 1000000000, bit = 10; true; cur /= 10, --bit) {
		query(cur);
		if(s[0] == 'Y') {
			query(cur - 1);
			if(s[0] == 'Y') continue;
			work(bit);
			break;
		}
	}
	return 0;
}

