int findDigits() {
  for(int i = 9; i >= 1; i--) {
    check(pw[i] - 1);
    if(no()) {
      return i + 1;
    }
  }

  for(int i = 1; i <= 9; i++) {
    check(pw[i]);
    if(no()) {
      return i;
    }
  }
  return 0;
}

int getDigit(int f, LL cur) {
  if(nextZero) return 0;
  nextZero = 0;
  int lo = f, hi = 8;
  int idx = f;

  while(lo <= hi) {
    int mi = (lo + hi) >> 1;
    LL tmp = cur * 10 + mi;
    while(tmp < 1e12) tmp *= 10;
    check(tmp);
    if(no()) {
      idx = mi;
      lo = mi + 1;
    } else {
      hi = mi - 1;
    }
  }

  // check idx and idx + 1
  LL tmp = cur * 10 + idx + 1;
  while(tmp < 1e12) tmp *= 10;
  check(tmp - 1);
  if(yes()) {
    return idx;
  }
  // nextZero means next number is 0
  nextZero = 1;
  return idx + 1;
}

