        r *= 10;
        int i = lower_bound(1, 10, [&](int i) {
            // n>Nなのでstr(n)>str(N)が返る ただしj==0&&i==0&&N==10^Kのときは両方逆になって上手くいく
            return query((r + i) * pow10(K)); // iが大きくなるほど満たされやすくなる条件
