	}
	reverse(kouho.begin(), kouho.end());
	bool flag = false;
	{
		string st(to_string(kouho[0]));
		if (all_of(st.begin(), st.end(), [](const char&c) {return c == '9'; }))flag = true;
	}
	int ans = -1;
	for (int i = 0; i < kouho.size(); ++i) {
		bool aa = check(kouho[i] + 1);
		if (aa^(flag&&i==0)) {
			ans = kouho[i];
			break;
		}
	}
	if (ans == -1)assert(false);
	cout << "! " << ans << endl;
	flush(cout);
	return 0;
