int main()
{
    ios::sync_with_stdio(false);

    int digit_num = 0;
    for (int i=0; i<12; i++) {
        string n = "1";
        if (i>0) n += string(i, '0');
        if (!query(n)) {
            digit_num = i;
            break;
        }
    }

    if (digit_num > 10) {
        cout << "! 1" << endl;
        return 0;
    }
    // DUMP(digit_num);

    string now = "";
    for (int i=0; i<digit_num-1; i++) {
        int ub = 10, lb = 0;
        while (abs(ub - lb) > 1) {
            int mid = (ub + lb) / 2;
            string n = now;
            n += (mid + '0');
            (query(n) ? lb : ub) = mid;
        }

        if (lb == ub - 1) {
            now += lb + '0';
        } else {
            assert(false);
        }
    }

    {   
        int ub = 9, lb = -1;
        while (abs(ub - lb) > 1) {
            int mid = (ub + lb) / 2;
            string n = now;
            n += (mid + '0');
            n += '9';
            (query(n) ? ub : lb) = mid;
        }
        if (ub == lb + 1) {
            now += ub + '0';
        } else {
            assert(false);
        }
    }

    cout << "! " << now << endl;
}

