  rep(i,1,15) pw[i] = pw[i - 1] * 10;
  int x = findDigits();
  if(!x) {
    putAns(1);
  } else if(x == 10) {
    putAns(pw[9]);
  }
  LL ans = 0;
  rep(i,1,x+1) {
    int d = getDigit(i == 1, ans);
    ans = ans * 10 + d;
  }
  putAns(ans);
  return 0;
}

