void solve() {
    long long lo = (long long) 1e9, hi = (long long) 1e10 - 1;
    while (lo < hi) {
        long long mi = lo + hi >> 1;
        if (ask(mi) == "N") {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    long long x = (lo + hi >> 1);
    FOR(i, 0, 10) {
        x /= 10;
        if (x % 10 < 9 && ask(x + 1) == "N") {
            answer(x * 10);
            break;
        }
        if (x % 10) {
            if (ask(x - 1) == "Y") {
                answer(x);
                break;
            }
        }
    }
}

