	int sit = 0;
	for (int i = 1; i < N; ++ i){
		if (flag && sit){
			break;
		}
		if (query(power[i - 1]) && query(power[i] - 1)){
			sit = i;
		}
	}
	for (int i = 0; i < sit - 1; ++ i){
