		}
		int left = !i, right = 9;
		for (int mid = left + right + 1 >> 1; left < right; mid = left + right + 1 >> 1){
			if (query(x + mid)){
				left = mid; 
			}
			else{
				right = mid - 1;
			}
		}
		ans[i] = left;
	}
	ll x = 0;
	for (int i = 0; i < sit - 1; ++ i){
		x += ans[i] * power[sit - i];
	}
