static int test(int k){
	ll lo = 1, hi = 9;
	for(int i = 1; i < k; ++i){
		lo *= 10;
		hi = (hi * 10 + 9);
	}
	return (query(lo) ? 1 : 0) | (query(hi) ? 2 : 0);
}

static int get_ndigits(){
	vector<int> t(12);
	for(int i = 1; i <= 11; ++i){ t[i] = test(i); }
	for(int i = 10; i >= 1; --i){
		if(t[i] != t.back()){
			if(t.back() == 3){
				return i + 1;
			}else{
				return i;
			}
		}
	}
	return 1;
}

