        N = NN;
        SN = to_string(N);
#ifdef LOCAL
        cerr << "N: " << N << endl;
#endif
    }
    bool query(ll n) {
        if (memo.count(n)) {
            return memo[n];
        }
        ++cnt;
        if (cnt > 64) {
            cerr << "Query Limit Exceeded" << endl;
            exit(1);
