#endif
);

int f(ll n) {
    int dig = 0;
    while (n > 0) {
        ++dig;
        n /= 10;
    }
    return dig;
}

ll padding(ll n, int digit = 16) {
    int dig = f(n);
    while (dig++ < digit) {
        n *= 10;
    }
    return n;
}

ll zero_leading(ll q, ll dig = -1) {
    cerr << "zero_leading" << endl;
    if (dig != -1) {
        int cur = f(q);
        while (cur++ < dig) {
            q *= 10;
        }
        jury.answer(q);
    }
    while (true) {
        if (jury.query(q + 1)) {
            jury.answer(q);
        }
        q *= 10;
    }
}

signed main() {

    // 答えが10の累乗
    if (jury.query(padding(1))) zero_leading(1);

    ll Q = 1, dig = 0;
    while (++dig) if (not jury.query(Q *= 10)) break;
    cerr << dig << endl;

    // 上から桁を決めていく
    ll q = 0;

    while (true) {
        int ng = 0, ok = 10;
        while (ok - ng > 1) {
            int mid = (ok + ng) / 2;
            if (jury.query(padding(10 * q + mid, dig + 1))) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        q = 10 * q + ok - 1;
        if (q > (int)1e9) {
            q += 1;
            while (q % 10 == 0) q /= 10;
            zero_leading(q, dig);
        }
    }

}

