int answer(std::function<bool(std::int64_t)>question)
{
	if (question(10000000000))
	{
		for (std::int64_t i = 9; i <= 9999999999; i *= 10, i += 9)
		{
			if (question(i))
			{
				return (i + 1) / 10;
			}
		}
	}
	else
	{
		std::int64_t min = 10;
		for (; min <= 10000000000; min *= 10)
		{
			if (!question(min))
			{
				break;
			}
		}
		std::int64_t max = 10 * min - 10;
		min /= 10;
		max /= 10;
		while (max - min > 1)
		{
			if (question(10 * ((max + min) / 2)))
			{
				max = (max + min) / 2;
			}
			else
			{
				min = (max + min) / 2;
			}
		}
		if (question(10 * max))
		{
			return max;
		}
		else if (question(10 * min))
		{
			return min;
		}
		else
		{
			return min - 1;
		}
	}
	return 0;
}

