bool Query(vector<int> d) {
  int64_t v = 0;
  for (int i = 0; i < d.size(); ++i) {
    v = v * 10 + d[i];
  }
  return Query(v);
}

int main() {
  int64_t ten = 1, k = -1;
  for (int i = 1; i <= 11; ++i) {
    bool v = Query(ten);
    if (v) k = i;
    ten = ten * 10;
  }
  if (k == 11) {
    int64_t val = 9;
    for (int i = 1; i <= 11; ++i) {
      if (Query(val)) {
        cout << "! 1";
        for (int j = 0; j < i - 1; ++j) cout << "0";
        cout << endl;
        return 0;
      }
      val = val * 10 + 9;
    }
  }
  assert(k != -1);
  vector<int> d(k + 1);
  for (int i = 0; i < k; ++i) {
    for (int g = 5; g >= 0; --g) {
      if (d[i] + (1 << g) >= 10) continue;
      d[i] += (1 << g);
      if (Query(d)) d[i] -= (1 << g);
