using namespace std;

int main() {
    auto query = [&]() {
        long long cur = 10;
        for (int i = 1; i <= 10; i++) {
            printf("? %lld\n", cur), fflush(stdout);
            char s[2]; scanf("%s", s);
            if (s[0] == 'N') return i;
            cur = cur * 10;
        }
        cur = 9;
        for (int i = 1; i <= 10; i++) {
            printf("? %lld\n", cur), fflush(stdout);
            char s[2]; scanf("%s", s);
            if (s[0] == 'Y') return i;
            cur = cur * 10 + 9;
        }
    };
    int len = query(), sum = 0;
    for (int i = 1; i <= len; i++) {
        int l = 0, r = 9, pw = 1, ans = 0;
        for (int j = 1; i + j <= len; j++) pw *= 10;
        while (l <= r) {
            int mid = (l + r) >> 1;
            printf("? %lld\n", (sum + mid * pw) * 10LL), fflush(stdout);
            char s[2]; scanf("%s", s);
            if (i < len) {
                if (s[0] == 'Y') r = mid - 1;
                else l = (ans = mid) + 1;
            } else {
                if (s[0] == 'Y') r = (ans = mid) - 1;
                else l = mid + 1;
            }
        }
        if (i == 1) ans = max(ans, 1);
        sum += pw * ans;
    }
    printf("! %d\n", sum);
    return 0;
}

