int should_procceed(LL now) {
	LL p10 = 1;
	int stat = 0;
	for (int i = 1; i <= 12; i++) {
		if (p10 == now) stat = 1;
		p10 *= 10;
	}

	if (!stat) {
		int x = check((now - 1) * 10 + 9);
		return x;
	}

	if (stat) {
		int x = check((now - 1) * 10 + 9);
		return 1 - x;
	}
}

int main()
{
	int first_digit = 9;
	for (int i = 1; i <= 9; i++) {
		if (check(i)) continue;
		else {
			first_digit = i - 1; break;
		}
	}
	LL now = first_digit;
	while (should_procceed(now)) {
		int nxt_digit = 9;
		for (int i = 0; i <= 9; i++) {
			if (check(now * 10 + i)) continue;
			else {
				nxt_digit = i - 1;
				break;
			}
		}
		now = (now * 10 + nxt_digit);
	}
	printf("! %lld\n", now);
	fflush(stdout);
	return 0;
}

