ll pow10(int n)
{
    if (n == 0){
        return 1;
    }else{
        return pow10(n - 1) * 10;
    }
}

int main()
{
    auto getAnswer = [](){
        return (getchar() == 'Y');
    };
    auto question = [](ll n){
        printf("? %lld\n", n); fflush(stdout);
    };
    question(pow10(9));
    if (getAnswer()){ // 1, 10, 100, ... , 1000000000
        int d_min = 0;
        int d_max = 9;
        while (d_min < d_max){ // 2分探索で桁を調べる
            int d_temp = (d_min + d_max) / 2;
            question(2 * pow10(d_temp));
            if (getAnswer()){
                d_max = d_temp;
            }else{
                d_min = d_temp + 1;
            }
        }
        printf("! %lld\n", pow10(d_min));
    }else{
        int d_min = 0;
        int d_max = 9;
        while (d_min < d_max){ // 2分探索で桁を調べる
            int d_temp = (d_min + d_max) / 2 + 1;
            question(pow10(d_temp));
            if (getAnswer()){
                d_min = d_temp;
            }else{
                d_max = d_temp - 1;
            }
        }
        // pow10(d_min) < N < pow10(d_min + 1)
        ll N_min = pow10(d_min) + 1;
        ll N_max = pow10(d_min + 1) - 1;
        while (N_min < N_max){ // 2分探索で値を調べる
            ll N_temp = (N_min + N_max) / 2;
            question(N_temp * 10);
            if (getAnswer()){
                N_max = N_temp;
            }else{
                N_min = N_temp + 1;
            }
        }
        printf("! %lld\n", N_min);
    }
}

