bool ok(int m, int res) {
	res = res * 10 + m;
	cout << "? " << res << endl;
	char c; cin >> c;
	return c == 'Y';
}

bool all_nine(int v) {
	while(v) {
		if(v % 10 != 9) return false;
		v /= 10;
	}
	return true;
}

void solve() {
	int res = 0;
	for(int i = 0; i < 10; i++) {
		int lv, rv = 10;
		if(i == 0) lv = 1;
		else lv = 0;
		while(rv - lv > 1) {
			int m = (lv + rv) / 2;
			if(ok(m, res)) lv = m;
			else rv = m;
		}
		res = res * 10 + lv;
		cout << "? " << res + 1 << endl;
		char c; cin >> c;
		if(all_nine(res)) {
			if(c == 'N') {
				cout << "! " << res << endl;
				return;
			}
		}
		else {
			if(c == 'Y') {
				cout << "! " << res << endl;
				return;
			}
		}
	}
}

