int main(){

    int dig = 10;
    int ask = 999999999;
    while(dig > 1){
        if(!inquire(ask))break;
        ask /= 10, dig--;
    }

    if(dig == 1){
        lint use = lintpow(10, 9) - 10;
        int last = 9;
        while(last > 1){
            if(!inquire((use + 1) * lintpow(10, 9 - last) - 1))break;
            use = use / 100 * 10, last--;
        }
        if(last > 1){
