		ask(2);
		int a = 20;
		while(!rec()){
			ask(a);
			a *= 10;
			wei++;
		}
		cout << "! " << a / 20 << endl;
		return 0;
	}else{
		ask(1);
		int a = 10;
		while(rec()){
			ask(a);
			a *= 10;
			wei++;
		}
	}
	//二分找数
	int a = 1;
	for(int i = 1;i <= wei;i++) a *= 10;
	int l = a/10,r = a-1,mid;
	while(l < r){
		mid = (l+r) >> 1;
		ask(mid*10);
		bool u = rec();
		if(u) r = mid;
		else l = mid;
	}
	cout << "! " << l << endl;

	return 0;
}

