// NがL桁の整数だと仮定すると、L桁の整数nとNの大小はstr(n)とstr(N)の大小と一致する
// 10nとNの大小は？ n<Nのときstr(10n)<str(N) n>=Nのときstr(10n)>str(N)
// つまり"? 10n"に対してYが返ってくるL桁の最小の整数nがNってことになる 桁数Lがわかれば二分探索できる
// Lは"? 10^(k-1)"にYが返ってくる最大のkで求められる
// ただしNが10^aって形の場合は例外で "? 10^k"に対してはkをどこまで大きくしてもYが返ってきてしまう
// この場合だけ"? 2*10^k"でYが返ってくる最小のkがL

int l, le, ri;

bool q(ll n) {
	cout << "? " << n << ln << flush;
	char c;
	cin >> c;
	return c=='Y';
}

void fin(ll n) {
	cout << "! " << n << ln << flush;
}

signed main() {
	bool ten = false;
	rep(i,10) {
		if (!q(pow(10ll,i))) {
			l = i-1;
			break;
		}
		if (i==9) ten = true;
	}
	// N = 10^a
	if (ten) {
		rep(i,10) {
			if (q(pow(10ll,i)*2)) {
				fin(pow(10ll,i));
				return 0;
			}
		}
	}
	// N != 10^a
	else {
		le = pow(10ll,l), ri = le*10;
		while (ri-le>1) {
			int m = (le+ri)/2;
			if (q(m*10)) ri = m;
			else le = m;
		}
		fin(ri);
	}
}

#include <bits/stdc++.h>
using namespace std;

int pw(int n,int k){
  assert(k>=0);
  int res=1;
  while(k){
    if(k&1)res*=n;
    n*=n;
    k>>=1;
  }
  return res;
}

