bool solve()
{
  query.clear();
  long long size, start = 0, last = 10, putN = false;
  while (start < last) {
    long long middle = (start + last) / 2;

    string ans;
    if (query.count(middle)) {
      ans = query[middle];
    } else {
      cout << "? 1" + string(middle, '0') + "\n";
      cout.flush();
      cin >> ans;
      //ans = q('1' + string(middle, '0'));
      query[middle] = ans;
    }
    if (ans == "Y") {
      start = middle + 1;
    } else {
      putN = true;
      last = middle;
    }
  }
  if(!putN) {
    start = 0, last = 10;
    while (start < last) {
      long long middle = (start + last) / 2;

      string ans;
