      if (ans == "Y") {
        last = middle;
      } else {
        start = middle + 1;
      }
    }
    cout << "! 1" << string(start, '0') << "\n";
    return pow(10LL, start) == setnum;
  }
  query.clear();
  size = start;
  start = pow(10LL, size - 1);
  last = pow(10LL, size) - 1;
  while (start < last) {
    long long middle = (start + last) / 2;

    string res;
    if(query.count(middle)) {
      res = query[middle];
    } else {
      cout << "? " << middle << "0\n";
      cout.flush();
      cin >> res;
      //res = q(to_string(middle * 10));
      query[middle] = res;
    }
    if (res == "Y") {
      last = middle;
    } else {
      start = middle + 1;
    }
  }
  cout << start << "\n";
  return start == setnum;
}

