void solve() {
    int cnt = 0, l = 0;
	for(int k = 0; k <= 9; ++k) {
        int t = (int)pow(10, k);
        if(query(t)) {
            cnt ++;
        } else {
            l = k;
            break;
        }
    }

    if(cnt == 10) {
        //pow(10, a)の形になると断言できる
        for(int k = 0; k <= 9; ++k) {
            int t = 2 * (int)pow(10, k);
            if(query(t)) {
                cout << "! " << (int)pow(10, k) << endl;
                exit(0);
            }
        }
    } else {
        //二部探索で特定する
        //ふつーに二部探索では特定できない？
        //各桁ごとに二部探索？

        int ng = (int)pow(10, l - 1), ok = (int)pow(10, l) - 1;
        while(ok - ng > 1) {
            int mid = (ok + ng) / 2;
            if(query(10 * mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        cout << "! " << ok << endl;
        exit(0);
        //桁が同じなら文字数で比較すればよいので10倍して比較すればok

        //２つ動かれると厄介なので、どちらかの返答を固定する！！
    }
}

