    }
    assert (0);
  }
  // not 10...0
  ll cur = 1;
  while (true) {
    if (not ask(cur)) {
      break;
    }
    cur *= 10;
  }
  // cur / 10 < n < cur
  ll lo = cur / 10;
  ll hi = cur;
  while (hi - lo > 1) {
    ll mid = (hi + lo) / 2;
    if (ask(10 * mid)) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  output(hi);
}

