#include "bits/stdc++.h"

using namespace std;

const int INF = 1e9 + 7;

map<long long, string> query;

void solve()
{
  long long size, start = 0, last = 10;
  while(start < last) {
    long long middle = (start + last) / 2;

    string ans;
    if(query.count(middle)) {
      ans = query[middle];
    } else {
      cout << "? 1" + string(middle, '0') + "\n";
      cout.flush();
      cin >> ans;
      query[middle] = ans;
    }
    if(ans == "Y") {
      start = middle + (start == middle);
    }else {
      last = middle;
    }
  }
  query.clear();
  size = start;
  start = pow(10LL, size - 1);
  last = pow(10LL, size) - 1;
  while (start < last) {
    long long middle = (start + last) / 2;

    string res;
    if(query.count(middle)) {
      res = query[middle];
    } else {
      cout << "? " << middle << "0\n";
      cout.flush();
      cin >> res;
      res = query[middle];
    }
    if (res == "Y") {
      last = middle;
    } else {
      start = middle + (start == middle);
    }
  }
  cout << "! " << start << "\n";
}

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  solve();
}

