lint bs(lint mn,lint mx,function<bool(lint)> func){
    mn--;
    mx++;
	while(mx-mn>1){
		lint mid=(mn+mx)/2;
		if(!func(mid))mx=mid;
		else mn=mid;
	}
    return mn;
}

