  for(int i=1; i<=9; i++) {
    if (ans[i] != 0) {
      flag = false;
    }
  }

  if (flag) {
    int ret = 1e+9;
    while (ret > 1) {
      char c;
      c = check(ret-1);
      if (c == 'N') {
        cout << "! " << ret << endl;
        return 0;
      }
      ret /= 10;
    }
    cout << "! " << ret << endl;
    return 0;
  }
  // special case end

  ll ret = ans[0];
  for(int i=1; i<9; i++) {
    ret *= 10;
    ret += ans[i];
  }

  ll before;
  while(ret > 0) {
    char c;
    c = check((ret-1)*10);
    if (c == 'Y') {
      cout << "! " << before << endl;
      return 0;
    }
    before = ret;
    ret /= 10;
  }
  cout << "! " << before << endl;
  return 0;
}

