	rep(i,0,11)
	{
		ll l=kpow(10,i),r=kpow(10,i+1)-1;
		while(l<r)
		{

			if(p==-1)
			{
				ll mid=(l+r)/2;
				printf("? %lld\n",mid);
				fflush(stdout);
				scanf("%s",op);
				if(op[0]=='Y')l=mid+1;
