ll kpow(ll a, ll b) {
	ll r = 1;
	while (b > 0) {
		if (b & 1) r = r * a;
		a = a * a, b >>= 1;
	}
	return r;
}
bool check() {
	rep(i, 0, 10) 
		if (!qry(kpow(10, i)))
			return false;
	return true;
}
int len() {
	rep(i, 1, 10)
		if (!qry(kpow(10, i)))
			return i;
	return 10;
}
int main() {
	if (check()) {
		rep(p, 0, 10)
			if (qry(kpow(10, p + 1) - 1)) {
				cout << "! " << kpow(10, p) << endl;
				break;
			}
	} else {
		int L = len();
		ll pre = 0;
		rep(i, 0, L - 1) {
			int l = 0, r = 9;
			while (l + 1 < r) {
				int m = (l + r) >> 1;
				!qry(pre * 10  + m) ? r = m - 1 : l = m; 
			}
			int x;
			if (l == r) {
				x = l;
			} else {
				x = qry(pre * 10 + r) ? r : l;
			}
			pre = pre * 10 + x;
