  }

  num = makenum(num, ll);
  if (num == 1e11) {
    llong t = 2;
    while (!ask(t)) t *= 10;
    answer(t / 2);
  }
  while (!ask(num - 1)) num /= 10;
  answer(num);

  return 0;
}

