ll toInt (vector <int> x) {
	ll res = 0;
	for (auto to: x) {
		res *= 10;
		res += to;
	}
	return res;
}

void solve () {
	int l = 0, r = 10;   

	map <int, bool> mp; 
	while (r - l > 1) {
		int mid = (r + l) / 2;
		vector <int> v;
		v.pb (1);
		for (int i = 2; i <= mid; i ++)
			v.pb (0);

		ll x = toInt(v);
		if (!mp.count (x)) {
			cout << "? " << x << endl;
			char ans; cin >> ans;
			if (ans == 'Y')
				l = mid;
			else
				r = mid;
			mp[x] = ans;
		} else {
			if (mp[x]) {
				l = mid;
			} else {
			    r = mid;
			}
		}
	}

	vector <int> v;

	v.pb (1);
	for (int i = 2; i <= l; i ++)
		v.pb (0);

	for (int i = 0; i < sz (v); i ++) {
		int l = 0, r = 10;
		while (r - l > 1) {
			int mid = (r + l) / 2;
			v[i] = mid;

			ll x = toInt(v);
			if (!mp.count (x)) {
				cout << "? " << x << endl;
				char ans; cin >> ans;
				if (ans == 'Y')
					l = mid;
				else
					r = mid;
				mp[x] = ans;
			} else {
				if (mp[x]) {
					l = mid;
				} else {
				    r = mid;
				}
			}
		}
		v[i] = l;
	}

	cout << "! " << toInt (v);
}

main () { //fast_in;
    int t = 1; //cin >> t;
    while (t --) {
    	solve ();    
    }
	return 0;
}

