ll power[10] = {1LL, 10LL, 100LL, 1000LL, 10000LL, 100000LL, 1000000LL, 10000000LL, 100000000LL, 1000000000LL};

int main(void){
	if (ask(power[9])){
		// 10^n
		for(int i=8;i>=0;i--){
			if (!ask(power[i] + 1)){
				cout << "! " << power[i+1] << endl; return 0;
			}
		}
		cout << "! 1" << endl; return 0;
	}else{
		for(int i=8;i>=0;i--){
			if (ask(power[i])){
				// 10^i + 1 以上 10^{i+1} 未満
				ll ng = power[i], ok = power[i+1];
				while(llabs(ng - ok) > 1){
					ll mid = (ok + ng) / 2;
					if (ask(mid * 10)) ok = mid; else ng = mid;
				}
				cout << "! " << ok << endl; return 0;
			}
		}
	}
    return 0;
}

