    while (response!='Y'&&d1>0) {
      d1--;
      cout <<  "? " << (d10+(d1-1))*10 << endl;
      cin >> response;
    }
    result = d10+d1;
  }
  else {
    ll now = 1;
    response = ' ';
    while (response!='N') {
      now *= 10;
      cout << "? " << now-1 << endl;
      cin >> response;
    }
    result = now/10;
  }

  cout << "! " << result << endl;
