                    n = s + power(10, i - 2) * 3;
                    cout << "? " << n << endl;
                    cin >> ans;
                    if(ans == 'Y') s += power(10, i - 2) * 3;
                    else s += power(10, i - 2) * 2;
                }
                else{
                    n = s + power(10, i - 2) * 1;
                    cout << "? " << n << endl;
                    cin >> ans;
                    if(ans == 'Y') s += power(10, i - 2) * 1;
                    else s += power(10, i - 2) * 0;
                }
            }
        }
    }
    for(int i = 8; i >= 0; i--){
        cout << "? " << s * 100 + i * 10 << endl;
        cin >> ans;
        if(ans == 'N'){
            cout << "! " << s * 10 + i + 1 << endl;
            return 0;
        }
    }
    cout << "! " << s * 10 << endl;
}

