void bin(ll l,ll r){
    if(l>1e10){
        cout<<"! 1"<<endl;
        return;
    }
    ll m = (l+r)/2;
    bool yes = ques(m);
    if(m%10==9 && yes && (pow10(r)^ques(r))){
