		while(l <= r) {
			mid = l + r >> 1;
			query(ans * 10 + mid);
			if(s[0] == 'Y') {
				if(maxpos < mid) maxpos = mid;
				l = mid + 1;
			} else {
				r = mid - 1;
			}
		}
		ans = ans * 10 + maxpos;
	}
	maxpos = 0, l = 0, r = 9;
	while(l <= r) {
		mid = l + r >> 1;
		query((ans * 10 + mid) * 10);
		if(s[0] == 'N') {
			if(maxpos < mid) maxpos = mid;
			l = mid + 1;
		} else {
			r = mid - 1;
		}
	}
	ans = ans * 10 + maxpos;
	printf("! %d\n", ans);
	return;
}

int main() {
	for(int cur = 1000000000, bit = 10; true; cur /= 10, --bit) {
