        if (ask(mi) == "N") {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    long long x = (lo + hi >> 1);
    long long prv;
    FOR(i, 0, 10) {
        prv = x;
        x /= 10;
        FOR(k, 0, 10) {
            int r = x / p10[k] % 10;
            int found = 0;
            if (r && r < 9) {
                if (ask(x + p10[k]) == "N") {
                    answer(prv);
                    return;
                }
                found = 1;
            }
            if ((r > 1 || (r == 1 && x >= p10[k + 1]))) {
                if (ask(x - p10[k]) == "Y") {
                    answer(x);
                    return;
                }
                found = 1;
            }
            if (found) break;
        }
        if (x % 10) {
            answer(x);
            return;
        }
    }
}

