void search(int length) {
    LL left = 1;
    while(--length) left *= 10;
    LL right = left * 10 - 1;
    left++;
    while (left < right) {
        LL mid = (left+right+1) >> 1;
        mid *= 10;
        cout << "? " << mid << endl;
        char c = input();
        if (c == 'Y') {
            right = mid / 10 - 1;
        }
        else {
            left = mid / 10;
        }
    }
    cout << "! " << left << endl;
}

