int bs(ll x, bool z){
	int l = 1, r = 9;
	if (z)l = 0;
	while (r > l){
		int m = l + r + 1 >> 1;
		ll t = x * 10 + m;
		if (q(t))l = m;
		else r = m - 1;
	}
	if (l < 9)return l;
	ll t = x * 10 + 9;
	ll tt = fl(t);
	if (q(tt)){
		int l = 0, r = 9;
