	int H,L;
	L = 1;
	H = 10;
	LL ket10 = powMod(10,keta-1);
	LL ans;
	while(H-L>1){
		int mid = (L+H)/2;
		LL temp = mid*ket10;
		if( query( temp*10 ) ){
			H = mid;
		}else{
			L = mid;
		}
	}
	ans = L*ket10;
	--keta;
	ket10 /= 10;
	while( keta ){
		L = 0;
		H = 10;
		while(H-L>1){
			int mid = (L+H)/2;
			LL temp = (ans + mid*ket10) * 10;
			if( query( temp ) ){
				H = mid;
			}else{
				L = mid;
			}
		}
		if( keta > 1 ){
			ans += L * ket10;
		}else{
			ans += H;
		}
		--keta;
		ket10 /= 10;
	}
	cout << "! " << ans << endl;
}
