ll solve() {
	ll l=1;
	while(l*10<=MAXN) l*=10;
	if(query(l)&&query(10*l)&&query(l-1)) {
		l=1;
		while(!query(l+1)) l*=10;
		return l;
	}
	while(true) {
		if(!query(l-1)) break;
		if(!query(l)) { l/=10; continue; }
		break;
	}
	ll r=min(10*l,(ll)MAXN+1);
	while(l+1<r) {
		ll m=l+(r-l)/2;
		if(!query(10*(m-1))) l=m; else r=m;
	}
	return l;
}

