#endif
}

void solve() {
    if (ask(1e18)) {
        rep(i, 10) {
            int n = pow(10, i+1) - 1;
            if (ask(n)) {
                ans((n+1) / 10);
                return;
            }
        }
    } else {
        ll top;
        for (top = 1; top <= (ll)1e10; top *= 10) {
            if (!ask(top)) break;
        }
        top /= 10;
        dump(top);
        ll l = top;
        ll r = top*10;
        while (l + 1 < r) {
            ll m = (l + r) / 2;
            if (ask(m*10)) {
                r = m;
            } else {
                l = m;
            }
        }
        ans(r);
    }
}

