int _main()
{
        char n[13];
        memset(n, '9', sizeof(n));
        n[12] = 0;
        int idx = 0;
        bool first = true;

        for ( ; ; ++idx) {

                char left = 0;
                char right = 9;
                char val = (left + right) / 2;
                char cand = 10;

                if (first) left = 1;
                first = false;

                for ( ; left <= right; val = (left + right) / 2) {
                        n[idx] = val + '0';
                        cout << "? " << n << endl << flush;
                        string res;
                        CIN(res);
                        if (res == "Y") {
                                cand = min(cand, val);
                                right = val - 1;
                        }
                        if (res == "N") {
                                left = val + 1;
                        }
                }
                n[idx] = cand + '0';

                if (n[idx] == '0') {
                        char check[13];
                        ll checkans;
                        bool corner = false;
                        memcpy(check, n, sizeof(check));

                        if (check[idx-1] == '9') {
                                check[idx-1] = '1';
                                check[idx] = '9';
                                check[idx+1] = 0;
                                sscanf(check, "%lld", &checkans);
                                corner = true;
                        }
                        else {
                                check[idx] = 0;
                                sscanf(check, "%lld", &checkans);
                                checkans++;
                        }

                        cout << "? " << checkans << endl << flush;
                        string res;
                        CIN(res);

                        if (!corner && res == "Y") {
                                cout << "! " << check << endl << flush;
                                return 0;
                        }
                        if (corner && res == "N") {
                                n[idx] = 0;
                                cout << "! " << n << endl << flush;
                                return 0;
                        }
                }

        }

        return 0;
}

