	return 0;
}
int query0(long long x) {
	while(x < 10000000000LL) x *= 10;
	return query(x - 1);
}
int get(int old) {
	int ans = 0;
	for(int i = 8; i; i >>= 1) {
		if(ans + i > 9) continue;
		if(old == 0 && ans == 0 && i == 1) {
			return 1;
		}
		if(!query0((old * 10 + (ans + i)))) 
			ans += i;
	}
	return ans;
}
int main() {
	int ans = get(0), t;
	bool onezero = ans == 1;
	for(int i = 2; i <= 10; ++i) {
		t = get(ans);
		if(t == 0) {
			if(onezero) {
				if(query(ans * 10 - 1)) return print(ans); 
			} else {
				if(!query(ans * 10 - 1)) return print(ans);
			}
		} else onezero = false;
		ans = ans * 10 + t;
	}
	return print(ans);
}

