    inline T operator()(int l, int r) {
        assert(l <= r);
        return rui[r] - rui[l];
    }
    inline T operator[](int i) {
        return rui[i];
    }
};

template<class T> struct rruic {
    const T *rrui;
    rruic(T *ru) : rrui(ru) {}
    //n-1から-1へ
