        nums[1] = 1;
        nums[2] = 7;
        nums[4] = 11;
        nums[8] = 13;
        nums[16] = 17;
        nums[32] = 19;
        nums[64] = 23;
        nums[128] = 29;
        //p = 30i + j
        int j = 0;
        int sflim = era.flags_.size();
        int i30 = 0;
        for (int i = 0; i < sflim; i++, i30 += 30) {
            uint8_t m = era.flags_[i];
            while (m) {
                j = m & -m;
                primes.push_back(i30 + nums[j]);
                m ^= j;
            }
        }
