int main () {
	int res = 0, j;
	for (int i = j = 1; i; i *= 10, ++j) {
		if (!ask(0, i)) { S = j - 1; break; }
		if (i == 1e9) { S = 9; break; }
	}
	if (!S) return ask(1, 0), 0;
	if (S == 9) return ask(1, 1e9), 0;
	for (int i = j = 1; i < S; ++i, res *= 10) {
		int l = 1, r = 9, mid;
		while (l <= r) {
			mid = (l + r) >> 1;
			if (!ask(0, res + mid)) r = mid - 1;
			else l = mid + 1;
		}
		res += (l - 1);
	}
	for (int i = 0; i <= 9; ++i) {
		if (ask(0, (i + res) * 10)) return ask(1, i + res), 0;
	}
	ask(1, res);
	return 0;
}
