{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    S bool flags[12];
    srep (digits, 1, 12) flags[digits] = is_possible(digits);

    ll ans_digits = -1LL;

    if (flags[11]) {
        srep (digits, 1, 12) {
            if (flags[digits]) {
                ans_digits = digits;
                break;
            }
        }
    }
    else if (flags[1]) {
        srep (digits, 1, 12) {
            if (!flags[digits]) {
                ans_digits = digits - 1LL;
                break;
            }
        }
    }
    else {
        srep (digits, 1, 12) {
            if (flags[digits]) {
                ans_digits = digits;
                break;
            }
        }
    }

    assert(ans_digits >= 1LL);

    ll left = (ll)pow(10LL, ans_digits);
    ll right = (ll)pow(10LL, ans_digits + 1LL) - 1LL;
    ll now = (left + right) / 2LL;
    ll ans = right;

    for ( ; left <= right; now = (left + right) / 2LL) {
        string a = ask(now);
        if (a == "Y") {
            ans = min(ans, now);
            right = now - 1LL;
        }
        if (a == "N") {
            left = now + 1LL;
        }
    }

    ans /= 10LL;
    cout << "! " << ans << endl;
    cout << flush;
}

