int main(){
	long long int ten = 1;
	long long int ten2 = 10;
	for (int i = 1; i <= 11; i++){
		bool A1 = query(ten);
		bool A2 = query(ten2 - 1);
		if (A1 == A2&&A1==true){
			long long int mint = ten;
			long long int maxt = ten2-1LL;
			while (mint + 1LL < maxt){
				long long int mid = (mint + maxt) >> 1LL;
				if (query(mid * 10LL)){
					maxt = mid;
				}
				else{
					mint = mid + 1LL;
				}
			}
			if (query(mint * 10LL)){
				outt(mint);
			}
			else{
				outt(maxt);
			}
		}
		ten *= 10;
		ten2 *= 10;
	}
	return 0;
}

