		REP(i, 0, 10) {
			if (query(q)) break;
			q *= 10;
		}
		while (str > q) str /= 10;
	} else {
		int q = 1;
		REP(i, 0, 10) {
			if (!query(q)) break;
			q *= 10;
		}
		while (str > q) str /= 10;
	}
	return str;
}

