  while(start < last) {
    long long middle = (start + last) / 2;

    string ans;
    if(query.count(middle)) {
      ans = query[middle];
    } else {
      cout << "? 1" + string(middle, '0') + "\n";
      cout.flush();
      cin >> ans;
      query[middle] = ans;
    }
    if(ans == "Y") {
      start = middle + 1;
    }else {
      last = middle;
    }
  }
  query.clear();
  size = start;
  start = pow(10LL, size - 1);
  last = pow(10LL, size) - 1;
  while (start < last) {
    long long middle = (start + last) / 2;

