int should_procceed(LL now) {
	LL p10 = 1;
	int stat = 0;
	for (int i = 1; i <= 12; i++) {
		if (p10 == now) stat = 1;
		p10 *= 10;
	}
	if (!stat) {
		int x = check((now - 1) * 10 + 9);
		return x;
	}

	if (stat) {
		int x = check((now - 1) * 10 + 9);
		return 1 - x;
	}
}

