#define ll long long
using namespace std;


ll GetNumber(const string& S) {
    ll x=0;
    for(int i=0;i<S.size();i++) {
        x = x*10+S[i]-'0';
    }
    return x;
}

int numdigs(ll x) {
    int ct=0;
    while(x) {
        ct++;
        x/=10;
    }
    return ct;
}

bool done;
string Solve(const string& pref, int st) {





    if (numdigs(GetNumber(pref)*10-1) == pref.size()) {
        ll curr = GetNumber(pref)*10-1;
        printf("? %lld\n",curr);
        fflush(stdout);
        string S;
        cin>>S;

        if (S[0]=='N') {
            printf("? %lld\n",curr*10+9);
            fflush(stdout);
            cin>>S;
            string ret=pref;
            ret.push_back('0');
            if (S[0]=='Y') {
                done=true;
                return ret;
            }
        }
    }


    // st to 9.
    int low=st;
    int high=9;
    while(low < high) {
        int mid = (low + high + 1)/2;
        printf("? %s%d\n",pref.c_str(),mid);
        fflush(stdout);
        string S;
        cin>>S;
        if (S[0]=='Y') {
            low = mid;
        } else {
            high = mid - 1;
        }
    }


    string ret=pref;
    ret.push_back(low+'0');
    return ret;
}

int main() {
    string pref = "";

    done=false;
    for(int iters=0;;iters++) {
        string nxt = Solve(pref, iters==0?1:0);
        if (nxt == pref)
            break;
        pref=nxt;
        if (pref.size() >= 10) {
            pref = "1";
            break;
        }
        if (done)
            break;
    }

    printf("! %s\n",pref.c_str());
    fflush(stdout);

}

