	ll s = 1;
	bool bad = 0;
	while(1) {
		if(ask(s)) {
			len++;
			s *= 10;
		} else {
			break;
		}
		if(len == 13) {
			bad = 1;
			break;
		}
	}
	if(bad) {
		len = 1, s = 1;
		while(1) {
			if(ask(s)) {
				len++;
				s *= 10;
				if(ask(s - 1)) break;
			} else {
				break;
			}
		}
	}
	len--;
