bool query(long long x){//if N is lexicographically <x
  if(x==0)return false;
  while(x<=10000000000ll)x=x*10;
  printf("? %lld\n",x-1);
  fflush(stdout);
  char buf[10];
  scanf("%s",buf);
  return buf[0]=='Y';
}
bool onlyone(int x){
  if(x==0)return false;
  while(x%10==0)x/=10;
  return x==1;
}
bool ok(int ans){
  char buf[10];
  printf("? %lld\n",ans*10ll-1);fflush(stdout);
  scanf("%s",buf);
  if(onlyone(ans)){
    return buf[0]=='Y';
  }else{
    return buf[0]=='N';
  }
}
