void getfirst(){
  int l=1,r=9;
  while(l<=r){
    if(l==r&&l==1){
      ans=1;return;
    }
    int mid=(l+r)>>1;
    if(query(mid))r=mid-1;
    else l=mid+1;
  }
  ans=r;
}
int main(){
  getfirst();
  while(1){
    int l=0,r=9;
    while(l<=r){
      int mid=(l+r)>>1;
