    {
        ll base=1;
        for(int i=0; i<9;++i){
            cout << "? " << base << endl;
            char c; cin >> c;
            if(c=='N') {
                sz=i;
                break;
            } 
            base *= 10;
        }
    }

    if(sz==-1) {
        ll base=9,base10=1;
        for(int i=0; i<10;++i){
            cout << "? " << base << endl;
            char c; cin >> c;
            if(c=='Y') {
                cout << "! " << base10 << endl;
                return 0;
            }
            base *= 10;
            base += 9;
            base10 *= 10;
        }        
    }

    if(sz == 1) {
        ll base=10;
        for(int i=1; i<10;++i){
            cout << "? " << base*i << endl;
            char c; cin >> c;
            if(c=='Y') {
                cout << "! " << i << endl;
                return 0;
            }
        }        
    }

    ll pre=0;
    {
        for(int i=sz; 2<=i;--i){
            ll base = 1;
            for(int j=0;j+2<i;++j) base *= 10;
            ll ok=0,ng=10,md;
            while(ng-ok>1) {
                md = (ok+ng)/2;
                ll cnt = pre/10 + base*md;
                cout << "? " << cnt << endl;
                char c; cin >> c;
                (c=='Y'?ok:ng)=md;
            }
            pre += base*10*ok;
        }        
    }

    {
        ll base=10;
        for(int i=0; i<10;++i){
            ll cnt = pre*10 + base*i;
            cout << "? " << cnt << endl;
            char c; cin >> c;
            if(c=='Y') {
                cout << "! " << pre+i << endl;
                return 0;
            }
        }        
    }

    return 0;
}

