int main() {
  ll MAX_N = 1000000000;

#ifdef LOCAL
  scanf("%lld", &TEST_ANS);
#endif

  bool onezero = query(MAX_N * 10);

  if (onezero) {
    ll ans = 1;
    while(1) {
      bool p = query(ans * 10 - 1);
      if (p) {
        answer(ans);
        return 0;
      }
      ans *= 10;
    }
  } else {
    ll digits = 0, ans = 1;

    while(1) {
      bool p = query(ans * 10);
      if (!p) {
        break;
      }
      digits++;
      ans *= 10;
    }

    ll l = ans, r = ans * 10 -1;

    while(l < r) {
      ll mid = (l + r) /2;

      if (query(mid * 10)) {
        r = mid;
      } else {
        l = mid + 1;
      }
    }

    answer(l);
  }

  return 0;
}

