            cur = cur * 10 + 9;
        }
    };
    int len = query(), sum = 0;
    for (int i = 1; i <= len; i++) {
        int l = 0, r = 9, pw = 1, ans;
        for (int j = 1; i + j <= len; j++) pw *= 10;
        while (l <= r) {
            int mid = (l + r) >> 1;
