int main(){
	int l=1,r=12;
	while(l!=r){
		int mid=(l+r)>>1;
		string str;
		for(int i=1;i<=mid;i++)
			str+='9';
		ask(str);
		if(check()) r=mid;
		else l=mid+1;
	}
	int len=r;
	string ans;
	for(int i=1;i<=len;i++){
		if(i<len){
			l=i==0?1:0,r=10;
			while(r-l>1){
				int mid=(l+r)>>1;
				ask(ans+(char)('0'+mid));
				if(check()) l=mid;
				else r=mid;
			}
			ans+=(char)(l+'0');
		}else{
			l=i==0?0:-1,r=9;
			while(r-l>1){
				int mid=(l+r)>>1;
				ask(ans+(char)('0'+mid)+('0'));
				if(check()) r=mid;
				else l=mid;
			}
			ans+=(char)(r+'0');
		}
	}
	print_ans(ans);
	return 0;
}

