bool query_less(LL n) {
	while (n <= 1000000000) {
		n *= 10;
		n += 9;
	}
	return query(n);
}

LL search_rec(LL str, bool f = false) {
	if (query_less(str * 10 + 4)) {
		REP(i, f ? 1 : 0, 5) {
			if (query_less(str * 10 + i)) return str * 10 + i;
		}
	} else {
		REP(i, 5, 10) {
			if (query_less(str * 10 + i)) return str * 10 + i;
		}
	}
}

LL search() {
	LL str = 0;
	REP(i, 0, 11) {
		str = search_rec(str, i == 0);
	}

	if (str == 1000000000) {
		LL q = 5;
		REP(i, 0, 10) {
			if (query(q)) break;
			q *= 10;
		}
		while (str > q) str /= 10;
	} else {
		LL q = 1;
		REP(i, 0, 10) {
			if (!query(q)) break;
			q *= 10;
		}
		while (str > q) str /= 10;
	}
	return str;
}

int main() {
	determine(search());
	return 0;
}

