char findDigit(std::string s, int start, std::string suffix){
    int64_t lb = 9, ub = start - 1;

    while(std::abs(ub - lb) > 1){
        int64_t mid = (lb + ub) / 2;

        ask(s + (char)(mid + '0') + suffix);
        char ans = answer();
        if(ans == 'Y'){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    return (char)(lb + '0');
}

