long long query, ans;
char c;

long long po(int k){
    long long x = 10, ans = 1;
    while (k){
        if (k&1) ans *= x;
        x = x * x;
        k >>= 1;
    }
    return ans;
}

bool ask(long long query){
    cout << "? " << query << "\n"; cout.flush();
    cin >> c;
    return c == 'Y';
}

