    for (int i = 10; i >= 0; i--){
        int l = (i == 10), r = 9;
        while (l != r){
            int mid = (l + r + 1) / 2;
            if (ask(query + mid * po(i+1))) r = mid-1;
            else l = mid;
        }
        if (ask((query + (r+1) * po(i+1)) / po(i+1))) {
            if (ask((query + r * po(i+1)) / po(i))) cout << "! " << (query + r * po(i+1)) / po(i+1) << "\n";
            else cout << "! " << (query + (r+1) * po(i+1)) / po(i+1) << "\n";
        }
        else {
            ans *= 10;
            ans += r;
            query += r * po(i+1);
        }
    }
    cout << "! " << ans << "\n";
}

