typedef long long int64;
const int DL = 3;
map<string, int> p2l;

vector<int64> tester;
int cmp(int64 a, int64 b)
{
  string x = to_string(a);
  string y = to_string(b);
  return a <= b && x <= y || a > b && x > y;
}

void init()
{
  for (int64 v = 1, i = 1; i <= DL; ++i, v = v * 10)
  tester.push_back(v);
  for (int64 v = 5, i = 1; i <= DL; ++i, v = v * 10)
  tester.push_back(v);
  for (int64 v = 9, i = 1; i <= DL; ++i, v = v * 10 + 9)
  tester.push_back(v);
  for (int l = 1; l <= DL; ++l)
  {
    for (int64 x: {1, 5, 9})
    for (int64 y: {0, 5, 9})
    {
      int64 v = x;
      for (int i = 1; i < l; ++i) v = v * 10 + y;
      string s;
      for (auto z: tester) s += '0' + cmp(v, z);
      auto where = p2l.find(s);
      if (where != p2l.end()) assert(where->second == l);
      else p2l[s] = l;
    }
  }
  if (0)
  for (int i = 1; i <= 999; ++i)
  {
    string s;
    for (auto z: tester) s += '0' + cmp(i, z);
    auto where = p2l.find(s);
    assert(where != p2l.end());
    assert(where->second == to_string(i).length());
    cerr << where->second << " " << i << endl;
  }
}

int get_length()
{
  string s;
  for (auto& iter: tester)
  {
    printf("? %lld\n", iter);
    char buff[32];
    scanf("%s", buff);
    s += buff[0] == 'Y' ? '1' : '0';
  }
  return p2l[s];
}

int main()
{
  init();
  int l = get_length();
  int64 a = 1, b = 9;
  for (int i = 1; i < l; ++i) a *= 10, b = b * 10 + 9;
  while (a <= b)
  {
    int64 mid = a + b >> 1;
    printf("? %lld0\n", mid);
    char buff[32];
    scanf("%s", buff);
    if (buff[0] == 'Y') a = mid + 1; else b = mid - 1;
  }
  printf("! %lld\n", b);
  return 0;
}

