int getKetaNum(long long start) {
	int buf = 5;
	if (getAns(buf + start)) {
		//4down
		buf = 3;
		if (getAns(buf + start)) {
			//2d
			buf = 2;
			if (getAns(buf + start)) {
				//1d
				buf = 1;
				if (getAns(buf + start)) {
					//0d
					buf = 0;
				}
				else {
					buf = 1;
				}
			}
			else {
				buf = 2;
			}
		}
		else {
			buf = 4;
			if (getAns(buf + start)) {
				buf = 3;
			}
			else {
				buf = 4;
			}
		}
	}
	else {
		//5up
		buf = 8;
		if (getAns(buf + start)) {
			//7d
			buf = 6;
			if (getAns(buf + start)) {
				buf = 5;
			}
			else {
				//6u
				buf = 7;
				if (getAns(buf + start)) {
					buf = 6;
				}
				else {
					buf = 7;
				}
			}
		}
		else {
			//8u
			buf = 9;
			if (getAns(buf + start)) {
				//8d
				buf = 8;
			}
			else {
				//9u
				buf = 9;
			}
		}
	}

	return buf;
}
int main(void) {
	long long keta_start = 9999999999L;
	int keta = 11;
	while (keta > 0) {

		if (!getAns(keta_start)) {
			break;
		}
		keta_start /= 10;
		keta--;
	}
	if (keta == 0) {
		cout << "! 0" << endl << flush;
		return 0;
	}

	long long start = 0;
	int count = 1;
	while (true) {
		int keta_num = getKetaNum(start);
		start += keta_num;
		if (count == keta) {
			break;
		}
		count++;
		start *= 10;
	}
	cout << "! " << start << endl << flush;

	return 0;
}

