void fin(ll n) {
	cout << "! " << n << ln << flush;
}

signed main() {
	rep(i,10) {
		if (!q(pow(10ll,i))) {
			l = i-1;
			break;
		}
	}
	// N = 10^a
	if (l==0) {
		rep(i,10) {
			if (q(pow(10ll,i)*2)) {
				fin(pow(10ll,i));
				return 0;
			}
		}
	}
	// N != 10^a
	else {
		le = pow(10ll,l), ri = le*10;
		while (ri-le>1) {
			int m = (le+ri)/2;
			if (q(m*10)) ri = m;
			else le = m;
		}
		fin(ri);
	}
}

