int getDigits() {
  int lo = 0, hi = 10;
  while (lo < hi) {
    int mid = (lo + hi) / 2;
    if (mid == 0) {
      break;
    }
    if (query(getAllNines(mid))) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  if (lo != hi) {
    return 666;
  }
  return lo;
}


ll getAns(int d) {
  if (query(getAllNines(d)+1)) {
    return getAllNines(d-1)+1;
  }
  ll ret = 0;
  for (int i = 1 ; i <= d ; i++) {
    int lo = 0, hi = 9;
    int check = 0;
    if (i == d) {
      check = 9;
    }
    while (lo < hi) {
      int mid = (lo + hi + 1) / 2;
      if (i == d) {
        mid = (lo + hi) / 2;
      }
      if (query(getAllNines(d-i+1, ret * 10 + mid, check))) {
        if (i == d) {
          hi = mid;
        } else {
          hi = mid-1;
        }
      } else {
        if (i == d) {
          lo = mid + 1;
        } else {
          lo = mid;
        }
      }
    }
    ret *= 10;
    ret += lo;
  }
  return ret;
}


