        if(ans == 'N') break;
    }

    if(i == 10)
    {
        // n : 10の階乗のとき
        cand = 1;
        for(int j = 0; j < 10; j++)
        {
            cand *= 10;
            cout << "? " << cand-1 << endl;
            char ans;
            cin >> ans;
            if(ans == 'Y')
            {
                cout << "! " << cand/10 << endl;
                return 0;
            }
        }
    }
    else
    {
        // i:桁数
        int num = 0;
        for(int k = 1; k <= i; k++)
        {
            int cand = 0;
            int d[4] = {8, 4, 2, 1};
            for(int j = 0; j < 4; j++)
            {
                if(cand + d[j] > 9) continue;
                cand += d[j];
                ll query = cand * 1e10 + num * 1e11;
                cout << "? " << query << endl;
                char ans;
                cin >> ans;
                if(ans == 'Y')
                {
                    cand -= d[j];
                }
                else
                {
                    cand += d[j];
                }
            }
            cand++;
            num += cand * pow(10, i-k);
        }
        cout << "! " << num << endl;
        return 0;
    }
}

