// finds lowest x: f(x) = true, x within [a, b), b if f(b - 1) = false
l binary_search_lower(l a, l b, function<bool(l)> f) {
  l count = b - a;
  while (count > 0) {
    l step = count / 2;
    l m = a + step;
    if (f(m)) {
      count = step;
    } else {
      a = m + 1;
      count -= step + 1;
    }
  }
  return a;
}

bool ask(l s, istream& cin, ostream& cout) {
  cout << "? " << s << endl;
  char c; cin >> c;
  return c == 'Y';
}

void solve(istream& cin, ostream& cout) {
  l answer = 0;
  while (true) {
    if (answer) {
      if (answer % 10 == 9) {
        if (not ask((answer - 1) * 10, cin, cout)) break;
      } else {
        if (ask(answer + 1, cin, cout)) break;
      }
    }
    // if (answer > 1 and not ask((answer - 1) * 10, cin, cout)) break;
    answer *= 10;
    answer += binary_search_lower(0, 9, [&](l x) {
        return ask((answer + x) * e9 + e9 - 1, cin, cout);
      });
    if (answer == 0) answer = 1;
  }
  cout << "! " << answer << endl;
}

