void solve() {
    static long long p10[20];
    p10[0] = 1; FOR(i, 1, 20) p10[i] = p10[i - 1] * 10;
    long long lo = (long long) 1e10, hi = (long long) 1e11 - 1;
    while (lo < hi) {
        long long mi = lo + hi >> 1;
        if (ask(mi) == "N") {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    long long x = (lo + hi >> 1);
    long long prv;
    FOR(i, 0, 10) {
        prv = x;
        x /= 10;
        if (x % 10) {
            answer(x);
            return;
        }
        FOR(k, 0, 10) {
            int r = x / p10[k] % 10;
            int found = 0;
            if (r && r < 9) {
                if (ask(x + p10[k]) == "N") {
                    answer(prv);
                    return;
                }
                found = 1;
            }
            if ((r > 1 || (r == 1 && x >= p10[k + 1]))) {
                if (ask(x - p10[k]) == "Y") {
                    answer(x);
                    return;
                }
                found = 1;
            }
            if (found) break;
        }
    }
}

