// 10^x (x>=0)
void sub() {
    const ll mi = 9;
    if (ask(mi) == 'Y') { // mi > N(値)
        bye(1);
    }

    // 10<=N<=10^9
    for (int n = 1e9; n >= 10; n /= 10) {
        if (ask(n - 1) == 'N') {
            bye(n);
        }
    }
}

