            s[i] = ('0' + mid);
            ll n = stoll(s);
            (ask(n) == 'Y' ? ub : lb) = mid;
        }
        s[i] = '0' + ub;
    }

    // 桁数
    for (int i = 1e9, d = 10; i >= 1; i /= 10, --d) {
        if (ask(i) == 'Y') {
            bye(stoll(s.substr(0, d)));
        }
    }
}

