int solve(){
    string N;
    // まずNの頭から文字を決定。二分探索。
    // N=123のとき、N=12299999....9
    // 文字列比較して求めるNより1ひくい11桁の数を出す。
    // ただしN=100のとき10..0を出すのでN=1eMの場合だけ
    // 別途場合分けする必要がある。
    for (int i = 0; i < 11; i++)
    {
        int ng=-1,ok=10;
        if(i==0) ng=1;
        while(ok-ng>1){
            int mid=(ok+ng)/2;
            string t=N;
            t += to_string(mid);
            t += string((11-t.length()),'0');
            DBG(t)
            if(throw_q(t)) ok=mid;
            else ng = mid;
        }
        if(ng!=-1) N += to_string(ng);
        else N += to_string(0);
    }

    ll ans=0;
    ans = stol(N);
    if(ans%10==9) ans++;

    ll m = ans;
    // 10..0だけややこしい。別。
    if(m==10000000000){
        m=1;
        // 下からなめる。
        // 10..0
        for (int i = N.length(); i > 0 ; i--)
        {
            m++;
            if(throw_q(m)) {ans=--m; break;}
            else --m;
            m*=10;
        }
    }
    else{
        // 上から舐める。
        // 12300..0
        for (int i = N.length(); i > 0 ; i--)
        {
            m/=10;
            m--;
            if(throw_q(m)) {ans=++m; break;}
            else m++;
        }
    }
    throw_a(ans);
    return 0;
}   

int editorial_solve(){
    ll m=1;
    while(throw_q(m) && m<=1e9) m*=10;
    int L;
    if(m==1e10){
        m=2;
        while(!throw_q(m) && m<=1e9) m*=10;
        L=log10(m/2)+1;
    }
    else
    {
        L=log10(m)+1;
    }
    // Nの桁数Lを決める。
    ll ng=pow(10,L-1);
    ll ok=ng*10-1;
    while(ok-ng>1){
        ll mid=(ok+ng)/2;
        if(throw_q(10*mid)) ok=mid;
        else ng = mid;
    }
    throw_a(ok);
}

