inline mint com(int n, int r) {
    if (r < 0 || r > n) return 0;
    return mint(finv[r] * fac[n] % MOD * finv[n - r]);
}
inline mint pom(int n, int r) {
//    if (!sz(fac)) com(0, -1);
    if (r < 0 || r > n) return 0;
