template<class T> struct ruiC {
    const vector<T> rui;
    ruiC(vector<T> &ru) : rui(ru) {}
    inline T operator()(int l, int r) {
        assert(l <= r);
        return rui[r] - rui[l];
    }
    inline T operator[](int i) {
        return rui[i];
    }
};

template<class T> struct rruic {
    const T *rrui;
    rruic(T *ru) : rrui(ru) {}
    //n-1から-1へ
    inline T operator()(int l, int r) {
        assert(l >= r);
        return rrui[r] - rrui[l];
    }
    inline T operator[](int i) { return rrui[i]; }
};
