	fflush(stdout);
	scanf("%s", in);
	return in[0] == 'Y';
}

void win(int an){
	printf("! %d\n", an);
	fflush(stdout);
	exit(0);
}

inline int dc(ll x){
	int an = 0;
	while (x)++an, x /= 10;
	return an;
}

inline ll fl(ll x){
	int d = dc(x);
	f(i, d, 15)x *= 10;
	return x;
}

int bs(ll x, bool z){
	int l = 1, r = 9;
	if (z)l = 0;
	while (r > l){
		int m = l + r + 1 >> 1;
		ll t = x * 10 + m;
		if (q(t))l = m;
		else r = m - 1;
	}
	if (l < 9)return l;
	ll t = x * 10 + 9;
	ll tt = fl(t);
	if (q(tt)){
		int l = 0, r = 9;
		if (!z)l = 1;
		ll tttt = x * 100 - 1;
		if (!z)tttt = 10;
		if (q(tttt))return 9;
		if (q((x * 10 + l) * 10))
		while (r > l){
			int m = l + r + 1 >> 1;
			ll ttt = x * 10 + m;
			if (q(ttt * 10 - 1))r = m - 1;
			else l = m;
		}
		win(x * 10 + l);
	}
	t = t * 10 - 1;
	if (q(t))return 0;
	win(x * 10 + 9);
	return 0;
}

int main(){
	ll an = 0;
	int t, bb = 0, ss = 0;
	while (true){
		++ss;
		if ((an = an * 10 + (t = bs(an, an))) > inf){
			int x = 1;
			f(i, 0, ss - bb)x *= 10;
			win(x);
		}
		if (t == 9)++bb; else bb = 0;
	}
}

