void ask(std::string n){
    std::cout << "? " << n << std::endl;
}

char answer(){
    char c;
    std::cin >> c;
    return c;
}

char findDigit(std::string s, int start){
    // if minimizing, lb satisfies lb > ub
    // if maximizing, lb satisfies lb < ub
    int64_t lb = start, ub = 10;

    while(std::abs(ub - lb) > 1){
        int64_t mid = (lb + ub) / 2;

        ask(s + (char)(mid + '0'));
        char ans = answer();
        if(ans == 'Y'){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    return (char)(lb + '0');
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::string res = "";
    while(true){
        char d = findDigit(res, res.size() == 0);
        if(d == '9'){
            // if minimizing, lb satisfies lb > ub
            // if maximizing, lb satisfies lb < ub
            // int64_t lb = -1, ub = 10;
            int64_t lb = 9, ub = res.size() == 0 ? 0 : -1;

            while(std::abs(ub - lb) > 1){
                int64_t mid = (lb + ub) / 2;

                ask(res + (char)(mid + '0') + '0');
                char ans = answer();
                if(ans == 'Y'){
                    lb = mid;
                }else{
                    ub = mid;
                }
            }

            res += (char)(lb + '0');

            break;
        }else{
            res += d;
        }
    }

    std::cout << "! " << res << std::endl;
}

