    ll n;
    out_stream.ignore(255, ' ');
    out_stream >> n;

    if(n <= trueNumber && to_string(n) <= to_string(trueNumber) ||
       n > trueNumber && to_string(n) > to_string(trueNumber)){
        in_stream << 'Y' << std::endl;
    }else{
