char findDigit(std::string s, int start, std::string suffix){
    int64_t lb = 9, ub = start - 1;

    while(std::abs(ub - lb) > 1){
        int64_t mid = (lb + ub) / 2;

        ask(s + (char)(mid + '0') + suffix);
        char ans = answer();
        if(ans == 'Y'){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    return (char)(lb + '0');
}

int main(int argc, char** argv){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    #ifdef DEBUG_FLAG
    trueNumber = stoll(argv[1]);
    #endif

    std::string res = "";    
    bool two = false;

    while(res.size() < 9 || (res.size() == 9 && !two)){
        char d = findDigit(res, res.size() == 0 ? 1 : 0, std::string(max<int>(0, 18 - 1 - res.size()), '9'));

        if(d > '0'){
            if(res.size() > 0){two = true;}
            res += d;
        }else{
            {
                ask(res + '9' + std::string(max<int>(0, 18 - 1 - 1 - res.size()), '0'));;
                char ans = answer();
                if(ans == 'N'){
                    res += '0';
                    continue;
                }
            }
            {
                ask(res + "1");
                char ans = answer();
                if(ans == 'N'){
                    res += '0';
                    continue;
                }
            }
            {
                ask(std::string(res.size(), '9'));
                char ans = answer();
                if(ans == 'N'){
                    res += '0';
                }
                break;
            }
        }
    }

    std::cout << "! " << res << std::endl;
}

