signed main()
{
	int a = 999999999;
	int keta = 0;

	for (int k = 0; k < 10; k++)
	{
		cout << "? " << a << endl;
		if (!IsY())
		{
			keta = 10 - k;
			break;
		}
		a /= 10;
	}

	if (keta == 10)
	{
		Ans(1000000000);
	}

	a = a * 10 + 9; //9999に戻す

	int ans = a;
	while (keta > 0)
	{
		int p = (int)pow(10, keta);

		int max = 9;
		int min = 0;

		while (true)
		{
			int m = (max - min) / 2 + min;

			int n_top = (ans / p) * p;
			int n_bottom = (ans % (p / 10));
			int n = n_top + (m * (p / 10)) + n_bottom;

			cout << "? " << n << endl;
			if (IsY())
			{
				max = m;
			}
			else
			{
				min = m;
			}

			if (max - min <= 1)
			{
				int ans_top = (ans / p) * p;
				int ans_bottom = (ans % (p / 10));
				ans = ans_top + (m * (p / 10)) + ans_bottom;
				break;
			}
		}

		keta--;
	}

	Ans(ans);
}

