        scanf("%c", &c);
        if (c == 'Y' || c == 'N') return c;
    }
}

void findzero() {
    int ret = 1;
    for (int i = 2; 2*i/2 == i; i *= 10) {
        cout << "? " << i << endl;
        char c = input();
        if (c == 'Y') {
            break;
        }
        else ret *= 10;
    }
    cout << "! " << ret << endl;
}
int findbase() {
    for (int i = 100000000; i >= 1; i /= 10) {
        cout << "? " << i << endl;
        char c = input();
        if (c == 'Y') {
            return i;
        }
    }
}
void search(LL base) {
    LL left = base + 1;
    LL right = base * 10 - 1;
    while (left < right) {
        LL mid = (left+right+1) >> 1;
        mid *= 10;
        cout << "? " << mid << endl;
        char c = input();
        if (c == 'Y') {
            right = mid / 10 - 1;
        }
        else {
            left = mid / 10;
        }
    }
    cout << "! " << left << endl;
}

int main() {
    cout << "? " << 1000000000 << endl;
    char c = input();
    if (c == 'Y') {
        findzero();
    }
    else {
        int base = findbase();
        search(base);
    }
    return 0;
}

