bool flush(ll n) {
  assert(1 <= n && n <= 1000000000000000000);
  cout << "? " << n << endl;
  char c;
  cin >> c;
  return (c == 'Y');
}

void answer(ll n) {
  assert(1 <= n && n <= 1000000000);
  cout << "! " << n << endl;
}

void solve1() {
  ll ask = 2;
  while (true) {
    if (flush(ask)) {
      answer(ask/2);
      return;
    } else {
      ask *= 10;
    }
  }
}

void solve2() {
  ll ask = 1e8;
  while (true) {
    if (flush(ask)) {
      break;
    } else {
      ask /= 10;
    }
  }
  ll lb = ask;
  ll ub = ask * 10 - 1;
  while (ub - lb > 1) {
    ll t = (ub + lb) / 2;
    if (flush(t * 10)) {
      ub = t;
    } else {
      lb = t;
    }
  }
  answer(ub);
}

int main () {
  if (flush(1e9)) {
    solve1();
  } else {
    solve2();
  }
}

