long long p(int n, int k) {
	if (k == 0) return 1ll;
	if (k == 1) return n;
	long long cur = p(n, k/2);
	if (k % 2 == 0) {
		return cur * cur;
	}
	else {
		return cur * cur * n;
	}
}

