        bestt.resize((sn << 1) - 1);
        rep(i, k)bestt[i + sn - 1] = i;//時間を持つ
        rer(i, sn - 2) {
            int lt = (i << 1) + 1, rt = (i << 1) + 2;
            if (dep[bestt[lt]] < dep[bestt[rt]]) {
                bestt[i] = bestt[lt];
            } else {
                bestt[i] = bestt[rt];
            }
        }
    }
    //最小の深さを持つタイミングが知りたい
    inline int lca_rmq(int l, int r) {
        int midv = inf;
        int midi = -1;
        l += sn - 1;
        r += sn - 1;
        while (l < r) {
            //右なら、次に右上へ移動してしまうので
            if (!(l & 1)) {
                if (chmi(midv, dep[bestt[l]])) {
                    midi = bestt[l];
                }
            }
            //右なら、左を取らないと機会を逃す
            if (!(r & 1)) {
                if (chmi(midv, dep[bestt[r - 1]])) {
                    midi = bestt[r - 1];
                }
            }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return vis[midi];
    }

public:
    tree(int n, int root = 0) : undigraph<T>(n), root(root) {}
    bool leaf(int v) {
        return sz(g[v]) == 1 && v != root;
    }
    int lca(int u, int v) {
        if (never)built();
        if (first[u] > first[v])swap(u, v);
        return lca_rmq(first[u], first[v] + 1);
    }
    int dis(int u, int v) {
        if (never) built();
        if (first[u] > first[v])swap(u, v);
        int p = lca_rmq(first[u], first[v] + 1);
        return disv[u] + disv[v] - disv[p] * 2;
    }

};
