void bin(int l,int r){
    int m = (l+r)/2;
    bool yes = ques(m);
    if(m%10==9 && yes && ques(m+1)){
        for(int n=m-9;n<=m;n++){
            if(ques(n*10)){
                cout<<"! "<<n<<endl;
                return;
            }
        }
    }

    if(l==r){
        if(!yes) m--;
        bin(m*10,m*10+9); 
    }
    else if(yes) bin(m+1,r);
    else bin(l,m-1);
}

