long long int binary_search_2(long long int lef, long long int rig){
	long long int middle = (lef + rig + 1) / 2;
	//cout << middle << " ";
	if(rig - lef <= 1){
		if(check(rig)){
			return rig;
		}else{
			return lef;
		}
	}
	if(check(middle)){
		lef = middle;
	}else{
		rig = middle;
	}
	return binary_search_2(lef, rig);
}

