int digcnt(llong num) { return num == 0 ? 0 : digcnt(num / 10) + 1; } 

llong makenum(llong head, llong l, int fill = 9) {
  for (l -= digcnt(head); l > 0; --l) head = head * 10 + fill;
  return head;
}

