template<typename T>
struct SegmentTree{
  using F = function<T(T,T)>;
  vector<T> data;
  ll n,lastlen = 1;
  F func = [](T a, T b){return a < b ? a : b;};
  T iden = MP(INT_MAX,0); //identity element
  SegmentTree(vector<T> v){
    n = (ll)v.size();
    while(lastlen < n)lastlen *= 2;
    data.assign(lastlen*2-1,iden);
    for(ll i=0;i<n;i++)data[i+lastlen-1] = v[i];
    for(ll i=lastlen-2;i>=0;i--){
      data[i] = func(data[2*i+1], data[2*i+2]);
    }
  }
  void update(ll point, T x){
    point+=lastlen-1;
    data[point] = x;
    while(point!=0){
      point=(point-1)/2;
      data[point]=func(data[2*point+1],data[2*point+2]);
    }
  }
  T query(ll a,ll b,ll point=0,ll left=0,ll right=-1){
    if(right<0)right=lastlen;
    T ret = iden;
    if(b <= left || right <= a);
    else if(a <= left && right <= b ){
      ret = func(ret, data[point]);
    }
    else{
      T p,q;
      p = query(a,b,point*2+1,left, (left+right)/2);
      q = query(a,b,point*2+2,(left+right)/2, right);
      ret = func(ret,p);
      ret = func(ret,q);
    }      
    return ret;
  }
};
vector<ll>a(220000);
vector<vector<ll>>g(220000);
vector<P>ret;
vector<P>ppppp(220000,MP(INT_MAX,0));
struct SegmentTree<P>seg1(ppppp);
struct SegmentTree<P>seg2(ppppp);
ll solve(ll l,ll r){
  if(r-l<=1)return 0;
  ll x=INF,xidx=-1,y=INF,yidx=-2;
  P p,q;
  if(l%2==0){
    p=seg1.query(l,r);
    q=seg2.query(p.se,r);
  }
  else{
    p=seg2.query(l,r);
    q=seg1.query(p.se,r);
  }
  x=p.fi,xidx=p.se,y=q.fi,yidx=q.se;
  ll idx=ret.size();
  ret.EB(x,y); 
  //cout<<xidx spa yidx<<endl;
  if(l<xidx)g[idx].PB(solve(l,xidx));
  if(yidx+1<r)g[idx].PB(solve(yidx+1,r));
  if(xidx+2<yidx)g[idx].PB(solve(xidx+1,yidx));
  return idx;
}
