        for(int i=9;i;i--){
            query(x-1);
            if(s[0]=='N')
                break;
            x/=10;
        }
        printf("! %d\n",x/10);
        return 0;
    }
    for(int i=9;i;i--){
        x/=10;
        query(x);
        if(s[0]=='Y')
            break;
    }
    int l=x+1,r=x*10-1,mid,ans;
    while(l<=r){
        mid=(l+r)>>1;
        query(mid*10);
        if(s[0]=='N')
            l=mid+1;
        else
            r=mid-1,ans=mid;
    }
    printf("! %d\n",ans);
    return 0;
}

