void num_to_str(llint x, char C[]) {
	for (int i = 0; i < MAXL; ++i) C[i] = 0;
	for (int i = 0; x > 0; ++i, x /= 10) {
		C[i] = (x % 10) + '0';
	}
	reverse(C, C+strlen(C));
}

bool cmp_lesseq(llint x, llint y) {
	num_to_str(x, A);
	num_to_str(y, B);
#ifdef DEBUG
	printf("CONVERTED: %s %s %d\n", A, B, strcmp(A, B));
#endif
	return strcmp(A, B) <= 0;
}

bool ask(llint x) {
