		ret = (x <= N && cmp_lesseq(x, N)) || (x > N && !cmp_lesseq(x, N));
		printf("%lld ANS:%d\n", x, ret);
	#else
		printf("? %lld\n", x);
		fflush(stdout);
		scanf("%s", C);
		ret = strcmp("Yes", C);
	#endif
	return ret;
}

