bool check(string pref) {
	if (pref[0] == '1') {
		string query = "";
		for (int i = 0; i < len(pref) - 1; i++) {
			query += '9';
		}
		return !ask(query, false);
	} else {
		pref[0] = '1';
		return ask(pref, false);
	}
}

