string get_a(long long v){
	string ret = "1";
	for(long long i = 0; i < v - 1; ++i){
		ret += "0";
	}
	return ret;
}

string get_b(long long v){
	string ret = "";
	for(long long i = 0; i < v; ++i){
		ret += "9";
	}
	return ret;
}

long long get_len(){
	long long lo = 1, hi = 10, ret = 1;
	while(lo <= hi){
		long long mid = (lo + hi) / 2;
		string a = get_a(mid);
		string b = get_b(mid);
		long long A = get(a);
		if(!A){
			hi = mid - 1;
			continue;
		}
		long long B = get(b);
		if(B){
			ret = mid;
			hi = mid - 1;
		}
		else lo = mid + 1;
	}
	return ret;
}

string fix(string f, long long v, long long len){
	char c = v + '0';
	f += c;
	while(f.size() < len) f += "9";
	return f;
}

