int num_digits(uint32_t n) {
  int count;

  while(n != 0) {
    n /= 10;
    count ++;
  }

  return count;
}

int pow(int base, int exp) {
  if (exp == 0)
    return 1;

  if (exp % 2 == 0) {
    int tmp = pow(base, exp / 2);
    return tmp * tmp;
  } else {
    return base * pow(base, exp - 1);
  }
}

