      upper = n - 1;
    } else {
      lower = n;
      break;
    }
  }

  while (lower < upper) {
    mid = (lower + upper) / 2;

    printf("? %d", mid * 10);
    fflush(stdout);
    scanf(" %c", &ans);

    if (ans == 'Y') {
      upper = mid;
    } else {
      lower = mid + 1;
    }
  }

  printf("! %d\n", lower);

  return 0;
}

