    string tmp = num + digit;
    tmp.append(15 - tmp.size(), '9');
    bool res = (ask(tmp) == 'Y');
//    cerr << tmp << ": " << res << endl;
    return res;
}

int getceil(char l, char r)
{
    while (r > l) {
        char m = (l + r) / 2;
        if (check(m)) r = m;
        else l = m+1;
//        cerr << l << ' ' << r << endl;
    }
    return r;
}

