	if(map.count(x)) return map[x];
	printf("? %lld\n", x);
	fflush(stdout);
	char ans[5];
	scanf("%s", ans);
	return map[x] = (ans[0] == 'Y');
}

void answer(ll x){
	printf("! %lld\n", x);
	exit(0);
}

bool solve(int len){
	ll now = 0;
	for(int i = 0; i < len - 1; ++ i){
		int left = 0, right = 9;
		ans[i] = -1;
		while(left <= right){
			int mid = left + right >> 1;
			if(ask(now * 10 + mid)){
				ans[i] = mid;
				left = mid + 1;
			}
			else{
				right = mid - 1;
			}
		}
		if(ans[i] == -1) return false;
		now = now * 10 + ans[i];
	}

	int left = 0, right = 9;
	while(left <= right){
		int mid = left + right >> 1;
		ans[len - 1] = -1;
		if(ask((now * 10 + mid) * 10)){
			ans[len - 1] = mid;
			right = mid - 1;
		}
		else{
			left = mid + 1;
		}
		if(ans[len - 1] == -1) return false;
	}

	now = now * 10 + ans[len - 1];
	if(now == 0) return false;
	answer(now);
	return true;
}

