string ask(ll num)
{
    if (num == 1LL) return "Y";

    S ll cnt = 0LL;

    cnt++;
    assert(cnt <= 64LL);

    cout << "? " << num << endl;
    cout << flush;

    string ret;
    CIN(ret);
    return ret;
}

bool is_possible(ll digits)
{
    string a1 = ask((ll)pow(10LL, digits - 1LL));
    string a2 = ask((ll)pow(10LL, digits) - 1LL);
    return (a1 == "Y") && (a2 == "Y");
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    S bool flags[12];
    srep (digits, 1, 12) flags[digits] = is_possible(digits);

    ll ans_digits = -1LL;

#if 0
    if (flags[11]) {
        srep (digits, 1, 12) {
            if (flags[digits]) {
                ans_digits = digits;
                break;
            }
        }
    }
#endif
    if (flags[1]) {
        srep (digits, 1, 12) {
            if (!flags[digits]) {
                ans_digits = digits - 1LL;
                break;
            }
        }
    }
    else {
        srep (digits, 1, 12) {
            if (flags[digits]) {
                ans_digits = digits;
                break;
            }
        }
    }

    if (ans_digits < 0LL) {
        cout << "! 1" << endl;
        cout << flush;
        return;
    }

    ll left = (ll)pow(10LL, ans_digits);
    ll right = (ll)pow(10LL, ans_digits + 1LL) - 1LL;
    ll now = (left + right) / 2LL;
    ll ans = right;

    for ( ; left <= right; now = (left + right) / 2LL) {
        string a = ask(now);
        if (a == "Y") {
            ans = min(ans, now);
            right = now - 1LL;
        }
        if (a == "N") {
            left = now + 1LL;
        }
    }

    ans /= 10LL;
    cout << "! " << ans << endl;
    cout << flush;
}

