static int test(int k){
	ll lo = 1, hi = 9;
	for(int i = 1; i < k; ++i){
		lo *= 10;
		hi = (hi * 10 + 9);
	}
	string s_lo, s_hi;
	cout << "? " << lo << endl << flush;
	cin >> s_lo;
	cout << "? " << hi << endl << flush;
	cin >> s_hi;
	return (s_lo == "Y" ? 1 : 0) | (s_hi == "Y" ? 2 : 0);
}

static int get_ndigits(){
	vector<int> t(12);
	for(int i = 1; i <= 11; ++i){ t[i] = test(i); }
	for(int i = 10; i >= 1; --i){
