 */
void compute() {
  ll keta = 0;
  _10[0] = 1, _99[0] = 9;
  REP(i,1,17) {
    _10[i] = _10[i-1] * 10LL;
    _99[i] = _99[i-1] * 10LL + 9LL;
  }

  {
    ll L = 0, R = 10;
    while( R - L ){
      ll M = ( L + R ) / 2LL;
      cout << "? "+to_string(_10[M]) << endl;
      //char c = AI("? "+to_string(_10[M]));
      char c;
      cin >> c;
      if( c == 'Y' ) L = M + 1LL;
      else           R = M;  
    }
    if( L-1LL == 9LL ) {
      keta = -1;
    } else {
      keta = L;
    }
  }

  if( keta == -1 ) {
    ll L = 0, R = 10;
    while( R - L ){
      ll M = ( L + R ) / 2LL;
      cout << "? "+to_string(_99[M]) << endl;
      //char c = AI("? "+to_string(_99[M]));
      char c;
      cin >> c;
      if( c == 'N' ) L = M + 1LL;
      else           R = M;  
    }
    if( L-1LL == 9LL ) {
      keta = -1;
    } else {
      keta = L+1;
    }
  }

  if( keta == 1 ) {
    cout << "? 10" << endl;
    //char c = AI("? 10");
    char c;
    cin >> c;
    if( c == 'Y' ) {
      cout <<"! 1" << endl;
      return;
    }
  }

  string s = "";
  rep(i,keta) {
    ll L = 0, R = 10;
    while( R - L ){
      ll M = ( L + R ) / 2LL;
      cout << "? "+s+to_string(M) << endl;
      //char c = AI("? "+s+to_string(M));
      char c;
      cin >> c;
      if( c == 'Y' ) L = M + 1LL;
      else           R = M;  
    }
    s += to_string(L-1LL);
  }
  //cout << "! " << s << endl;
  s = s.substr(0,(int)s.size()-1);

  {  
    ll L = 0, R = 10;
    while( R - L ){
      ll M = ( L + R ) / 2LL;
      cout << "? "+s+to_string(M)+"1" << endl;
      //char c = AI("? "+s+to_string(M)+"1");
      char c;
      cin >> c;
      if( c == 'N' ) L = M + 1LL;
      else           R = M;  
    }
    cout << "! " << s + to_string(L) << endl;
  }

}

