void finish(ll n) {
  cout << "! " << n << endl;
}

void solve() {
  ll n = 1e9;
  query(n);

  if (ans == 'Y') {
    rep(i,9) {
      query(n - 1);

      if (ans == 'N') {
        finish(n);
        return;
      }

      n /= 10;
    }

    finish(n);
    return;
  }

  int digit = 0;

  rrep1(i,9) {
    query(n / 10);

    if (ans == 'Y') {
      digit = i;
      break;
    }

    n /= 10;
  }

  ll l = 1;
  rep(i,digit) l *= 10;
  ll r = l * 10;

  while (r - l > 1) {
    ll mid = (r + l) / 2;

    query(mid * 10);

    if (ans == 'Y') r = mid;
    else l = mid;
  }

  finish(r);
  return;
}


