int get1()
{
    int low = 1, high = 10;
    int x;
    while(low <= high)
    {
        int mid = (low + high) / 2;
        x = 1;
        for(int i = 1; i <= mid; ++i) x *= 10LL;
        --x;
        if(ask(x, 0)) high = mid - 1;
        else low = mid + 1;
    }
    return low;
}

int get2()
{
    int low = 1, high = 10;
    int x;
    while(low <= high)
    {
        int mid = (low + high) / 2;
        x = 1;
        for(int i = 1; i < mid; ++i) x *= 10LL;
        if(ask(x, 0)) low = mid + 1;
        else high = mid - 1;
    }
    return high;
}

void solve()
{
    int len = -1;
    int cur = 0, ans = -1;
    for(int i = 1; i < 11; ++i)
    {
        int low = (i == 1 ? 1 : 0), high = 9;
        while(low <= high)
        {
            int mid = (low + high) / 2;
            if(ask(cur * 10 + mid, 1)) high = mid - 1;
            else low = mid + 1;
        }
        low = min(9LL, low);
        if(!ask(cur * 10 + low, 0)) --low;
        cur = cur * 10 + low;
        if(i == 1)
            len = (low < 9 ? get1() : get2());
        if(i == len)
        {
            ans = cur;
            break;
        }
    }
    cout << "! " << ans << endl;
