    // cerr << "query " << s << " " << atol(s.c_str()) << endl;
    ans_str = to_string(ans);
    bool b1 = atol(s.c_str()) <= ans,
        b2 = s <= ans_str;
    char ret = (b1 == b2 ? 'Y' : 'N');
    // cerr << "response " << ret << endl;
    return ret;
}

void answer(string s) {
    cerr << (s == ans_str ? "AC" : "WA")
         << " received answer " << s << ", expect " << ans_str << endl;
}
