            string str;
            cin >> str;
            if (str == "Y") {
                digit = sz(NINE);
                break;
            }
        }
    }

    ll left = 1, right = 1;
    rep(i, digit) {
        left *= 10;
        right *= 10;
    }
    left /= 10;
    left -= 1;
    while (right - left > 1) {
        ll mid = (right + left) / 2;
        cout << "? " << mid << "0" << endl;
        string str;
        cin >> str;
        if (str == "Y") right = mid;
        else left = mid;
    }

    cout << "! " << right << endl;
    return;
}

