int main()
{
    ll digit = -1;
    for (ll i = 0; i <= 9; i++) {
        const bool b = ask(pow(10, i));
        if (not b) {
            digit = i;
            break;
        }
    }
    if (digit == -1) {
        answer(1000000000);
        return 0;
    }
    ll inf = pow(10, digit - 1);
    ll sup = pow(10, digit);

    while (inf < sup) {
