typedef long long lint;

lint lintpow(const lint& x, const lint& p){
    lint res = 1, now = x, pow = p;
    for(; pow; pow >>= 1){
        if(pow & 1)res *= now;
        now *= now;
    }
    return res;
}

bool inquire(const lint& x){
    cout << "? " << x << endl;
    char c;
    cin >> c;
    return c == 'Y';
}

void answer(const int& x){
    cout << "! " << x << endl;
    exit(0);
}

// solve
int main(){

    int dig = 10;
    int ask = 999999999;
    while(dig > 1){
        if(!inquire(ask))break;
        ask /= 10, dig--;
    }

    if(dig == 1){
        lint use = lintpow(10, 9) - 10;
        int last = 9;
        while(last > 1){
            if(!inquire((use + 1) * lintpow(10, 9 - last) - 1))break;
            use = use / 100 * 10, last--;
        }
        if(last > 1){
            if(inquire(use * 10 + 9))answer(use * 10 + 90);
            for(int i = 8; i >= 0; --i){
                if(!inquire((use + i) * 10 + 9))answer(use + i + 1);
            }
        } else {
            for(int i = 8; i >= 1; --i){
                if(!inquire(i * 10 + 9))answer(i + 1);
            }
            if(inquire(100))answer(1);
            else answer(90);
        }
    } else {
        if(dig == 10)answer(ask + 1);
        lint use = lintpow(10, dig + 1) - 1;
        int ans = 0;
        rep(i, dig){
            int l = 0, r = 9;
            while(r - l > 1){
                int md = (l + r) / 2;
                (inquire(use + lintpow(10, dig - i) * (md - 9)) ? r : l) = md;
            }
            ans = ans * 10 + r;
            use -= lintpow(10, dig - i) * (9 - r);
            cout << r << endl;
        }
        answer(ans);
    }

}

