class Solve {
public:

    Int N = -1;

    void init() {
        cin >> N;
    }

    bool query(Int n) {
        string S;
        if (N == -1) {
            cout << n << endl;
            cin >> S;
        } else {
            bool ret = (n <= N) ^(to_string(n) <= to_string(N));
            if (!ret) {
                S = "Y";
            } else {
                S = "N";
            }
        }

//        cerr << "? " << n << endl;
//        cerr << S << endl;
//        cerr << " --- " << endl;

        return S == "Y";
    }

    void solve() {
        Int d = 11;
        while (d > 0) {
            bool f = query(static_cast<Int>(round(floor(pow(10ll, d - 1)))));
            if (f) {
                break;
            }
            d--;
        }
        if (d == 11) {
            while (d > 0) {
                bool f = query(2 * static_cast<Int>(round(floor(pow(10ll, d - 1)))));
                if (!f) {
                    break;
                }
                d--;
            }
            d++;
            Int ans = static_cast<Int>(round(floor(pow(10ll, d - 1))));
            cout << "! " << ans << endl;
            return;

        }

        Int ub = round(floor(pow(10, d)));
        Int lb = ub / 10;
        while (ub - lb > 1) {
            Int mid = (ub + lb) / 2;
            Int n = static_cast<Int>(mid * round(floor(pow(10, 9))));
            bool f = query(n);
            if (f) {
                ub = mid;
            } else {
                lb = mid;
            }
        }

        cout << "! " << lb + 1 << endl;
    }
};


