inline bool ask(ll n)
{
    cout << "? " << n << endl;
    char c;
    cin >> c;
    return (c == 'Y');
}

inline void answer(ll n)
{
    cout << "! " << n << endl;
}

int main()
{
    ll digit = -1;
    for (ll i = 0; i <= 10; i++) {
        const bool b = ask(pow(10, i));
        if (not b) {
            digit = i;
            break;
        }
    }
    if (digit == 10) {
        answer(1000000000);
        return 0;
    }

    ll inf = pow(10, digit - 1);
    ll sup = pow(10, digit);
    for (int i = 0; i < 50; i++) {
        const ll mid = (inf + sup) / 2;
        const bool b = ask(mid * 10);
        if (not b) {
            if (inf == mid) {
                break;
            }
            inf = mid;
        } else {
            if (mid == sup) {
                break;
            }
            sup = mid;
        }
    }
    if (not ask(sup - 1)) {
        answer(sup);
    } else {
        answer(sup - 1);
    }

    return 0;
}

