	}
	if (pos==-1){
		for (int i=1;i<=9;++i)
		if (query(ten[i]-1ll)) {pos=i-1;break;}
		if (pos==-1) pos=9;
		printf("! %lld",ten[pos]);fflush(stdout);
	}else{
		for (int i=1;i<=pos;++i){
			int l=(i==1),r=9,res=l;
			while (l<=r){
				int mid=(l+r)>>1;
				if (query((ans+1ll*mid*ten[pos-i])*10ll+ten[pos-i+1]-1ll)) res=mid,r=mid-1;
				else l=mid+1;
			}ans+=res*ten[pos-i];
		}printf("! %lld",ans);fflush(stdout);
	}return 0;
}

