int get1()
{
    int low = 1, high = 10;
    lli x;
    while(low <= high)
    {
        int mid = (low + high) / 2;
        x = 1;
        for(int i = 1; i <= mid; ++i) x *= 10LL;
        --x;
        if(ask(x, 0)) high = mid - 1;
        else low = mid + 1;
    }
    return low;
}

int get2()
{
    int low = 1, high = 10;
    lli x;
    while(low <= high)
    {
        int mid = (low + high) / 2;
        x = 1;
        for(int i = 1; i < mid; ++i) x *= 10LL;
        if(ask(x, 0)) low = mid + 1;
        else high = mid - 1;
    }
    return high;
}

