	int left = 0, right = 9;
	while(left <= right){
		int mid = left + right >> 1;
		if(ask((now * 10 + mid) * 10)){
			ans[len - 1] = mid;
			right = mid - 1;
		}
		else{
			left = mid + 1;
		}
	}

	now = now * 10 + ans[len - 1];

	answer(now);
	exit(0);
}

