void solve() {
	int ok = 0, ng = 11;
	//桁数をにぶたん
	//100...0のときやばい
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		string s = "1";
		REP(i, mid)s += '0';
		bool res = que(s);
		if (res)ok = mid;
		else ng = mid;
	}
	//100...0のとき
	if (ng == 11) {
		ok = 10, ng = 0;
		while (ok - ng > 1) {
			string s = "";
			int mid = (ok + ng) / 2;
			REP(i, mid)s += '9';
			bool res = que(s);
			if (res)ok = mid;
			else ng = mid;
		}
		string ans = "1";
		REP(i, ok - 1)ans += '0';
		end(ans);
	}
	//桁数=ng
	string ans;;
	string tmp = "";
	for (int k = ng; k > 0; k--) {
		string s = tmp;
		ok = 9, ng = 0;
		while (ok - ng > 1) {
			s = tmp;
			int mid = (ok + ng) / 2;
			s += (char)('0' + mid);
			REP(_, k)s += '0';
			bool res = que(s);
			if (res)ok = mid;
			else ng = mid;
		}
		char c = (char)(ok - 1 + '0');
		if (k == 1)c = (char)(ok + '0');
		ans += c;
		tmp += c;
	}
	end(ans);
}

