ll ones(int x){
	ll ret=0;
	for(;x--;) ret=10*ret+1;
	return ret;
}

ll get_kth(int k){
	--k;
	ll ret = 0;
	for(int dep=1; dep<=9; ++dep){
		if(!k && dep>1){
			break;
		}
		if(dep>1) --k;
		for(int i=(dep==1); i<=9; ++i){
			if(ones(10-dep) <= k){
				k -= ones(10-dep);
			} else {
				ret=10*ret + i;
				break;
			}
		}
	}
	return ret;
}

