{
    int i = 9, p = 1 << 3;
    while (p)
    {
        if ((i - p > 0) || ((i - p == 0) && (j != 1)))
        {
            ll q = (10LL * ans + (i - p)) * p10[len - j + 1] + p10[len - j + 1] - 1;
