int main(int argc, char *argv[])
{
  char ans;
  int out;

  int d = 9;
  for (; d >= 0; d--) {
    ll n = pow(10, d);

    printf("? %lld\n", n);
    fflush(stdout);
    scanf(" %c", &ans);

    if (ans == 'Y')
      break;
  }

  if (d == 9) {
    // N=10^m (m=0~9)

    int i = 0;

    ans = 'N';
