bool strc(int a,int b){
	string sa,sb; int len1,len2; stringstream ssa,ssb;
	ssa << a; sa = ssa.str(); ssb << b; sb = ssb.str();
    len1 = sa.length(); len2 = sb.length();
    if(len1 > len2) for(int i = 1;i <= len1-len2;i++) sb += '0';
    if(len1 < len2) for(int i = 1;i <= len2-len1;i++) sa += '0';
    for(int i = 0;i < max(len1,len2);i++){ if(sa[i] > sb[i]) return 1; if(sa[i] < sb[i]) return 0;}
	return 0;
}		//1:a > b	0:a <= b
