void bin(ll l,ll r){
    if(l+1==r){
        cout<<"! "<<r<<endl;
        return;        
    }
    ll m = (l+r)/2;
    bool yes = ques(m*10);
    if(yes) bin(l,m);
    else bin(m,r);
}

