int search_one(ll offset, int s_initial)
{
	int s, e, c, r, ans=0;

	s=s_initial;
	e=9;
	for(;s<=e;)
	{
		c=(s+e)/2;
		r=ask(c+offset);

		if(r)
		{
			s=c+1;
			ans=c;
		}
		else
		{
			e=c-1;
		}
	}
	return ans;
}


int search_last(ll offset)
{
	int s, e, c, r, ans=0;
	ll v;

	s=0;
	e=9;
	for(;s<=e;)
	{
		c=(s+e)/2;
		v=c+offset;
		r=ask(v*10);

		if(!r)
		{
			s=c+1;
		}
		else
		{
			e=c-1;
			ans=c;
		}
	}
	return ans;
}



