typedef long long ll;

bool query(ll x) {
	printf("? %lld\n", x);
	fflush(stdout);
	static char s[10];
	scanf("%s", s);
	return *s == 'Y';
}

int main() {
	ll test = 1;

	while(test <= 100000000000ll and query(test))
		test *= 10;

	if(test > 100000000000ll) {
		test = 9;
		while(!query(test))
			test = test * 10 + 9;
		printf("! %lld\n", test / 10 + 1);
		return 0;
	}

	ll l = test / 10, r = test - 1;
	while(l < r) {
		ll mid = (l + r) >> 1;
		if(query(mid * 10))
			r = mid;
		else
			l = mid + 1;
	}

	printf("! %lld\n", l);
}

