void solve() {
    // first figure out the length by querying 10, 100, 1000...
    int length = -1;
    for (int dc = 1; dc <= 9; dc++) {
        string q(dc + 1, '0');
        q.front() = '1';
        if (!query(q)) {
            length = dc;
            break;
        }
    }

    // number is one of 1, 10, 100, 1000, ...
    if (length == -1) {
        bool r11 = query("11");
        if (!r11) {
            for (int oc = 3; oc <= 10; oc++) {
                string q(oc, '1');
                if (query(q)) {
                    string a(oc, '0');
                    a.front() = '1';
                    finish(a);
                    return;
                }
            }
            assert(false);
        } else {
            finish(query("2") ? "1" : "10");
            return;
        }
    } else {
        // number isn't power of 10 and we know its length
        string res = "";
        F0R (i, length) {
            int lo = !i, hi = 10;
            while (lo < hi) {
                int mi = (lo + hi) / 2;
