	int beet = 1, usi = 0, i;
	for (i = 0; ; i++) {
		usi += beet * 9;
		beet *= 10;
		cout << "? " << usi << endl;
		cout.flush();
		char latte;
		cin >> latte;
		if (latte == 'Y') break;
	}
	return i + 1;
}

pair<int, bool> getDigit(int nowAns, int geta) {
	int st = -1, ed = 10, mid;	//xxxooo, (st, ed]
	while (ed - st >= 2) {
		mid = (st + ed) / 2;
		cout << "? " << (nowAns * 10 + mid) * geta << endl;
		cout.flush();
		char kuti;
		cin >> kuti;
		if (kuti == 'Y') { ed = mid; }
		else { st = mid; }
	}

	cout << "? " << (nowAns * 10 + ed) * geta - 1 << endl;
	cout.flush();
	char moti;
	cin >> moti;
	if (moti == 'N') return pair<int, bool>(ed, true);
	return pair<int, bool>(ed - 1, false);
}

signed main() {
	int ketasu = getKetasu(), i;
	int ans = 0;
	int p10[11];

	p10[0] = 1;
	for (i = 1; i < 11; i++) p10[i] = p10[i - 1] * 10;

	//答えが10^nの形かを判定
	cout << "? " << p10[10] << endl;
	cout.flush();
	char res;
	cin >> res;
	if (res == 'Y') { cout << p10[ketasu - 1] << endl; return 0; }

	//答えは10^nの形ではない
	int geta = p10[10];
	for (i = 0; i < ketasu; i++) {
		pair<int, bool> res = getDigit(ans, geta);
		ans *= 10;
		ans += res.first;
		geta /= 10;

		if (res.second) {
			cout << ans * p10[ketasu - 1 - i] << endl;
			break;
		}
	}
	return 0;
}

