int search_one(ll offset, int s_initial)
{
	int s, e, c, r, ans=0;

	s=s_initial;
	e=9;
	for(;s<=e;)
	{
//printf("s=%d e=%d c=%d offset=%lld\n", s, e, c, offset);
		c=(s+e)/2;
		r=ask(c+offset);
		if(r)
		{
			s=c+1;
			ans=c;
		}
		else
		{
			e=c-1;
		}
	}
	return ans;
}



int main(void)
{
	ll n, offset;
	int d;

	for(d=1,n=10;;d++,n*=10)
	{
		if(!ask(n)) break;
	}

	offset=0;
	for(int i=0;i+1<d;i++)
	{
		offset+=search_one(offset, i==0);
		offset*=10;
	}

	ll ans=offset;
	for(int i=9;i>=0;i--)
	{
		ll v=(offset+i);
		if(ask(v*10)) ans=v;
		else break;
	}

	printf("! %lld\n", ans);
	fflush(stdout);

	return 0;
}

