struct RandomNumberGenerator {
    mt19937 mt;
    RandomNumberGenerator() : mt(chrono::steady_clock::now().time_since_epoch().count()) {}
    int operator()(int a, int b) {  // [a, b)
        uniform_int_distribution<int> dist(a, b - 1);
        return dist(mt);
    }
    int operator()(int b) {         // [0, b)
        return (*this)(0, b);
    }
};

struct Jury {
    RandomNumberGenerator rng;
    int cnt, N;
    string SN;
    map<ll, bool> memo;
    Jury() : cnt(0) {
        rng = RandomNumberGenerator();
        N = rng((int)1e9) + 1;
        SN = to_string(N);
#ifdef LOCAL
        cerr << "N: " << N << endl;
#endif
    }
    Jury(int NN) : cnt(0) {
        N = NN;
        SN = to_string(N);
#ifdef LOCAL
        cerr << "N: " << N << endl;
#endif
    }
    bool query(ll n) {
        if (memo.count(n)) {
            return memo[n];
        }
        ++cnt;
        if (cnt > 64) {
            cerr << "Query Limit Exceeded" << endl;
            exit(1);
        }
#ifdef LOCAL
        string sn = to_string(n);
        bool f1 = n <= N;
        bool f2 = sn <= SN;
        cerr << cnt << " : " << n << " " << (f1 == f2 ? 'Y' : 'N') << endl;
        return memo[n] = f1 == f2;
#else
        cout << "? " << n << endl;
        char c; cin >> c;
        return memo[n] = c == 'Y';
#endif
    }
    void answer(ll n) {
#ifdef LOCAL
        if (n == N) {
            cerr << "AC : " << n << endl;
        } else {
            cerr << "WA : " << n << " " << N << endl;
        }
#else
        cout << "! " << n << endl;
#endif
        exit(0);
    }
} jury = Jury(
