int f(ll n) {
    int dig = 0;
    while (n > 0) {
        ++dig;
        n /= 10;
    }
    return dig;
}

ll padding(ll n, int digit = 16) {
    int dig = f(n);
    while (dig++ < digit) {
        n *= 10;
    }
    return n;
}

