ll zero_leading(ll q, ll dig = -1) {
    cerr << "zero_leading" << endl;
    if (dig != -1) {
        int cur = f(q);
        while (cur++ < dig) {
            q *= 10;
        }
        jury.answer(q);
    }
    while (true) {
        // if (pow10(q + 1)) { q *= 10; continue; }
        if (jury.query(q + 1)) {
            jury.answer(q);
        }
        q *= 10;
    }
}

