	forn(i, 1, 11) pw[i] = pw[i - 1] * 10;
	if(ASK(pw[11])) spj();
	int lb = 1, rb = 9;
	while(lb <= rb)
	{
		int mid = lb + rb >> 1;
		if(ASK(pw[mid])) lb = mid + 1;
		else rb = mid - 1;
	}
	int len = lb;
	LL cur = 0;
	rep(i, len)
	{
		if(i)
		{
			LL x = cur + pw[len - (i - 1)] - 1;
