bool check(char digit)
{
    if (digit == '9') return true;
    string tmp = num + digit;
    tmp.append(15 - tmp.size(), '9');
    bool res = (ask(tmp) == 'Y');
//    cerr << tmp << ": " << res << endl;
    return res;
}

int getceil(char l, char r)
{
    while (r > l) {
        char m = (l + r) / 2;
        if (check(m)) r = m;
        else l = m+1;
//        cerr << l << ' ' << r << endl;
    }
    return r;
}

int solve()
{
    while (true) {
        // maybe already true
        if (num.size() > 0) {
			bool full9 = 1;
			for (int i = 0; i < num.size(); ++i) {
				if (num[i] != '9') {
					full9 = 0;
					break;
				}
			}

			if (full9) {
				char ch = ask("1" + string(num.size(), '0'));
                if (ch == 'N') answer(num);
			} else {
                char ch = ask(to_string( stoll(num) + 1 ));
                if (ch == 'Y') answer(num);
			}
        }

        // binary search
        num += getceil('0', '9');
	}
	return 0;
}

int main()
{
    return solve();
}

