  l=0;
  r=9;
  while(r-l>1){
    m = (l+r)/2;
    if(ask(modPow(10, m, LINF))){
      l = m;
    }else{
      r = m;
    }
  }
  l = modPow(10, l, LINF);
  r = l*10;
  while(r-l>1){
    m = (l+r)/2;
    if(!ask(m*10)){
      l = m;
    }else{
      r = m;
    }
  }
  ans(r);
}

