void solve() {
    auto cur = 1ll;
    bool flag = false;

    for (int i = 0; !flag && i < 15; cur = 10 * cur, ++i)
        if (!req(cur))
            flag = true;

    if (!flag) {
        cur = 1ll;

        for (int i = 0; i < 15; cur = 10 * cur, ++i)
            if (req(cur + 1)) {
                cout << "! " << cur << endl;
                return ;
            }

        assert(false);
    }

    cur = max(1ll, cur / 100);
    auto l = cur;
    auto r = cur * 10 - 1;

    for (; l < r; ) {
        auto m = (l + r + 1) / 2;

        if (req(m * 10))
            r = m - 1;
        else
            l = m;
    }

    cout << "! " << r << endl;
}

