string ll_to_str(ll N) {
	string str;
	while(N) {
		str += (N % 10 + '0');
		N /= 10;
	}
	reverse(all(str));
	return str;
}

char get_ans(ll res) {
	string sn = ll_to_str(N);
	string sres = ll_to_str(res);
	bool s;
	if(N <= res && sn <= sres) s = true;
	else if(N > res && sn > sres) s = true;
	else s = false;
	return s ? 'Y' : 'N';
}

