		ll lv, rv = 10;
		if(i == 0) lv = 1;
		else lv = 0;
		while(rv - lv > 1) {
			ll m = (lv + rv) / 2;
			if(ok(res * 10 + m)) lv = m;
			else rv = m;
		}
		res = res * 10 + lv;
		//char c = get_ans(res + 1);
		cout << "? " << res + 1 << endl;
		char c; cin >> c;

		if((all_nine(res) && c == 'N') || (!all_nine(res) && c == 'Y')) {
			res -= 9;
			if(i == 0) lv = 0;
			else lv = -1;
			rv = 9;
			while(rv - lv > 1) {
				ll m = (lv + rv) / 2;
				if(ok(res * 10 + m * 10)) rv = m;
				else lv = m;
			}
			cout << "! " << res + rv << endl;
			return;
		}
	}
}

