}

void solve()
{
    int i;
    ll curr = 1;
    for (i = 1; i <= 10; i++) {
        if(i>1) curr = curr * 10;
        bool ok=ask(curr);
        if (!ok) {
            break;
        }
    }
    if (i == 11) {
        ll curr = 0;
        for (i = 1; i <= 10; i++) {
            curr = curr * 10 + 9;
            bool ok=ask(curr);
            if (ok) {
                break;
            }
        }
        //assert(i <= 9);
        int k;
        printf("! ");
        for (k = 0; k < i; k++) {
            if (k == 0) printf("1");
            else        printf("0");
        }
        printf("\n");
        fflush(stdout);
        return;
    }
    int keta = i-1;

    curr = 0;
    for (i = 1; i <= keta; i++) {
        int l = 0, r = 10;
        while (r - l > 1) {
            int m = (l + r) / 2;
            ll tmp0 = m;
            int k;
            for (k = 0; k < 9-(i-1); k++) {
                tmp0 *= 10;
            }
            ll tmp = curr + tmp0;
            bool ok = ask(tmp);
            if (ok) {
                r = m;
            }
            else {
                l = m;
            }
        }
        ll tmp0 = l;
        int k;
        for (k = 0; k < 9-(i-1); k++) {
            tmp0 *= 10;
        }
        curr += tmp0;
    }
    for (i = 1; i <= 9 - (keta - 1); i++) {
        curr /= 10;
    }
    printf("! %lld\n", curr+1);
    fflush(stdout);

    return;
}

