bool query(string x) {
	printf("? %s\n", x.c_str());
	fflush(stdout);
	char ans;
	scanf("%c", &ans);
	assert(false);
	return (ans == 'Y');
}

int main() {
	string fst = "0000000000";

	int lb = 1, ub = 10;
	while (ub - lb > 1) {
		int med = (lb + ub) / 2;
		if (query(char('0' + med) + fst)) ub = med;
		else lb = med;
	}

	string scd = char('0' + lb) + fst;
	string base = "";
	for_(i,1,12) {
		string q = scd.substr(0, i);
		if (!query(q)) {
			base = scd.substr(0, i-1);
			break;
		}
	}

	int k = base.size();
	for_(i,1,k) {
		lb = 0, ub = 10;
		while (ub - lb > 1) {
			int med = (lb + ub) / 2;
			string q = scd;
			q[i] = char('0' + med);
			if (query(q)) ub = med;
			else lb = med;
		}
		scd[i] = char('0' + lb);
		base[i] = scd[i];
	}
	printf("? %s\n", base.c_str());
	fflush(stdout);
}

