        return false;
    }
    string ans;
    cout << "? " << n << endl;
    cin >> ans;
    return ans[0] == 'Y';
}

int solve(){
    if(query(1e9)){
        for(LL i=2; i<=1e10; i*=10){
            if(query(i))return i/2;
        }
        return -1;
    }
    for(LL len=1e9; len>1; len/=10){
        if(!query(len/10))continue;
        LL lb = len/10;
        LL ub = len-1;
        while(ub-lb>1){
            LL mid = (lb+ub)>>1;
            bool res = query(mid*10);
            cerr << lb << " " << ub << " " << mid << " " << res << endl;
            if(res){
                ub = mid;
            }else{
                lb = mid;
            }
        }
        return ub;
    }
    return -1;
}

int main(){
    if(debug){
        cin >> N;
    }
    int res = solve();
    cout << "! " << res << endl;
    return 0;
}

