int main() {
	long long int amin = 1e8-1;
	long long int amax = 1e9-1;
	amin = 999;
	amax = 9999;
	while (amin + 1 != amax) {
		long long int amid = (amin + amax+1) / 2;
		if (check(amid*100)) {
			amax = amid;
		}
		else {
			amin = amid;
		}
	}
	vector<int>kouho;
	int t(amax);
	if (t == 1e8)t = 1e9;
	while (t) {
		kouho.push_back(t);
		if (t % 10)break;
		else t /= 10;
	}
	reverse(kouho.begin(), kouho.end());
	bool flag = false;
	{
		string st(to_string(kouho[0]));
		if (all_of(st.begin(), st.end(), [](const char&c) {return c == '9'; }))flag = true;
	}
	int ans = -1;
	for (int i = 0; i < kouho.size(); ++i) {
		bool aa = check(kouho[i] + 1);
		if (aa^(flag&&i==0)) {
			ans = kouho[i];
			break;
		}
	}
	if (ans == -1)assert(false);
	cout << "! " << ans << endl;
	flush(cout);
	return 0;
}

