ll fit(ll n)
{
    while(n < 10000000000ll)
        n *= 10;
    return n;
}

int main()
{
    ll now = 0;

    while(true)
    {
        int l = (!now) - 1, r = 10;
        while(l + 1 < r)
        {
            int m = (l + r) / 2;

            if(ask(now * 10 + m))
                l = m;
            else
                r = m;
        }

        if(r < 10)
            now = now * 10 + (r - 1);
        else if(ask(now? now * 100: 10))
        {
            if(!ask(now? fit(now): 100000000000ll))
                now = now * 10 + 9;
            else
            {
                now = now * 10 + (!now);
                break;
            }
        }
        else
        {
            int l = (!now) - 1, r = 10;
            while(l + 1 < r)
            {
                int m = (l + r) / 2;

                if(!ask(now * 100 + m * 10))
                    l = m;
                else
                    r = m;
            }

            if(r < 10)
                now = now * 10 + r;
            else
                now = now * 10 + 9;
            break;
        }
    }

    WTL('!', now);

}

