    p[0] = 1; FOR(i,1,18) p[i] = p[i-1] * 10;
    int digits = 0;
    while(1) {
        if(!check(p[digits])) break;
        digits++;
        if(digits > 11) {
            ll z = 1;
            FOR0(i, 11) if(!check(p[i] + 1)) {z = p[i+1];}
            cout << "! " << z<< endl; fflush(stdout);
            return 0;
        }
    }
    ll n = p[digits], x;
    FORD(i, 1, digits+1) {
        int l = (i == digits), r = 9; bool changed = false;
        while(l <= r) {
            int d = (l + r) >> 1;
            x = n + (d - ((n/p[i])%10))*p[i];
            if(check(x)) {r=d-1; n = x; changed = true;}
            else l = d+1; 
        }
        if(!changed) n = n + (1 - ((n/p[i])%10))*p[i];
    }
    cout << "! " << n/10<< endl;
    fflush(stdout);
    return 0;
}

