bool ask(ll N) {
	cout << "? " << N << endl;
	char X;
	cin >> X;
	if (X == 'Y')return 1;
	else return 0;
}

int main() {

	ll lv = 9999999999, rv = 99999999999, mid;
	while (rv - lv > 1) {
		mid = (lv + rv) / 2;
		if (ask(mid)) {
			rv = mid;
		}
		else {
			lv = mid;
		}
	}
	ll X = rv;
	while (X % 10 == 0) {
		if (!ask(X + 1)) {
			cout << "! " << X * 10 << endl;
			return 0;
		}
		X /= 10;
	}
	if (ask((X - 1) * 10)) {
		cout << "! " << X * 10 << endl;
	}
	else {
		cout << "! " << X << endl;
	}
}

