ll comi(int n, int r) {
    assert(n < 100);
    static vvi(pas, 100, 100);
    if (pas[0][0])return pas[n][r];
    pas[0][0] = 1;
    rep(i, 1, 100) {
        pas[i][0] = 1;
        rep(j, 1, i + 1)pas[i][j] = pas[i - 1][j - 1] + pas[i - 1][j];
    }
    return pas[n][r];
}
double comd(int n, int r) {
    assert(n < 2020);
    static vvd(comb, 2020, 2020);
    if (comb[0][0] == 0) {
        comb[0][0] = 1;
        rep(i, 2000) {
            comb[i + 1][0] = 1;
            rep(j, 1, i + 2) {
                comb[i + 1][j] = comb[i][j] + comb[i][j - 1];
            }
        }
    }
    return comb[n][r];
}
int gcd(int a, int b) {
    while (b) a %= b, swap(a, b);
    return abs(a);
}
int gcd(vi b) {
    ll res = b[0];
    rep(i, 1, sz(b))res = gcd(b[i], res);
