dou distance(pd a, pd b) { return hypot(a.fi - b.fi, a.se - b.se); }
//bを中心とするabcのtheta aからcにかけて時計回り
dou angle(pd a, pd b, pd c) {
    dou ax = a.fi - b.fi;
    dou ay = a.se - b.se;
    dou cx = c.fi - b.fi;
    dou cy = c.se - b.se;
    double ret = atan2(cy, cx) - atan2(ay, ax);
    if (ret < 0) ret += 2 * PI;
    return ret;
}

dou dot(pd a, pd b) { return a.fi * b.fi + a.se + b.se; }
