using namespace std;
vector<int> g[MAXN];
int depth[MAXN],subsize[MAXN];
int par[MAXN];
inline void dfs(int pos,int prev)
{
	depth[pos]=depth[prev]+1;
	par[pos]=prev;
	subsize[pos]=1;
	for(int i=0;i<g[pos].size();i++)
	{
		if(g[pos][i]!=prev)
		{
			dfs(g[pos][i],pos);
			subsize[pos]+=subsize[g[pos][i]];
		}
	}
}
bool mark[MAXN];
int fans=0;
int depth1[MAXN];
inline void dfs2(int pos,int prev,int req)
{
	depth1[pos]=depth1[prev]+1;
	for(int i=0;i<g[pos].size();i++)
	{	
		if(g[pos][i]!=prev)
		{
			dfs2(g[pos][i],pos,req);
		}
	}
	if(depth1[pos]<=req)
	{
		fans+=subsize[pos];
		for(int i=0;i<g[pos].size();i++)
		{
			if(g[pos][i]!=prev)
			{
				if(mark[g[pos][i]])
				{
					fans-=subsize[g[pos][i]];
					break;
				}
			}
		}
	}
}
