		g[y].pb(x);
	}
	dfs(1,0);
	int num=depth[n]-depth[1]-1;
	int x=n;
	while(x)
	{
		mark[x]=true;
		x=par[x];
	}
	int tt,lft=0;
	for(int i=0;i<g[1].size();i++)
	{
		if(!mark[g[1][i]])
		{
			lft+=subsize[g[1][i]];
		}
		else
		{
			tt=g[1][i];
		}
	}
	//cout<<lft<<" "<<tt<<"\n";
	assert(tt>0);
	dfs2(tt,1,(num/2)+(num%2));
	int rgt;
