int main(){
    static int64_t pow10[] = { 1, 10, 100, 1'000, 10'000, 100'000, 1'000'000, 10'000'000, 100'000'000, 1'000'000'000, 10'000'000'000 };
    if(query(pow10[9])){
        for(int i=0;i<9;++i) if(query(pow10[i+1]-1)) answer(pow10[i]);
        answer(pow10[9]);
    }else{
        int l = 0, r = 9;
        while(r - l > 1){
            int m = (l+r) / 2;
            if(query(pow10[m])) l = m;
            else r = m;
        }
        int64_t cand = -1, test = 0;
        for(int d=1;d<=r;++d){
            int dl = -1, dr = 10;
            if(d == 1) ++dl;
            while(dr - dl > 1){
                int m = (dl + dr) / 2;
                if(query(test+m*pow10[r+1-d])) dr = m;
                else dl = m;
            }
            if(dr == 0){
                answer(test);
            }else if(dl == 9){
                test += 9*pow10[r+1-d];
            }else{
                cand = test + dr*pow10[r+1-d];
                test += dl*pow10[r+1-d];
            }
        }
        answer(cand);
    }

    return 0;
}

