lint binsearch(lint l, lint r, function<bool(lint)> pred) {  // [l, r)
    assert(l < r);
    --l;
    while (r - l > 1) {
        lint m = (l + r) / 2;
        if (pred(m)) {
            r = m + 1;
        }
        else {
            l = m + 1;
        }
    }
    return r;
}

