ll GetNumber(const string& S) {
    ll x=0;
    for(int i=0;i<S.size();i++) {
        x = x*10+S[i]-'0';
    }
    return x;
}

int numdigs(ll x) {
    int ct=0;
    while(x) {
        ct++;
        x/=10;
    }
    return ct;
}

string Solve(const string& pref, int st) {

    if (!pref.empty()) {
        ll curr = GetNumber(pref)-1;
        if (numdigs(curr) == pref.size()) {
            printf("? %lld%d\n",curr,st);
            fflush(stdout);
            string S;
            cin>>S;
            if (S[0]=='N')
                return pref;
        }
    }


    // st to 9.
    int low=st;
    int high=9;
    while(low < high) {
        int mid = (low + high + 1)/2;
        printf("? %s%d\n",pref.c_str(),mid);
        fflush(stdout);
        string S;
        cin>>S;
        if (S[0]=='Y') {
            low = mid;
        } else {
            high = mid - 1;
        }
    }


    string ret=pref;
    ret.push_back(low+'0');
    return ret;
}

