ll N = 1000000000;


bool all_nine(ll v) {
	while(v) {
		if(v % 10 != 9) return false;
		v /= 10;
	}
	return true;
}


string ll_to_str(ll N) {
	string str;
	while(N) {
		str += (N % 10 + '0');
		N /= 10;
	}
	reverse(all(str));
	return str;
}

char get_ans(ll res) {
	string sn = ll_to_str(N);
	string sres = ll_to_str(res);
	bool s;
	if(N <= res && sn <= sres) s = true;
	else if(N > res && sn > sres) s = true;
	else s = false;
	return s ? 'Y' : 'N';
}

bool ok(ll res) {
	char c = get_ans(res);
	/*
	cout << "? " << res << endl;
	char c; cin >> c;
	*/
	return c == 'Y';
}


void solve() {
	ll res = 0;
	for(ll i = 0; i < 10; i++) {
		ll lv, rv = 10;
		if(i == 0) lv = 1;
		else lv = 0;
		while(rv - lv > 1) {
			ll m = (lv + rv) / 2;
			if(ok(res * 10 + m)) lv = m;
			else rv = m;
		}
		res = res * 10 + lv;
		char c = get_ans(res + 1);
		/*
		cout << "? " << res + 1 << endl;
		char c; cin >> c;
		*/

		if((all_nine(res) && c == 'N') || (!all_nine(res) && c == 'Y')) {
			res -= 9;
			if(i == 0) lv = 0;
			else lv = -1;
			rv = 9;
			while(rv - lv > 1) {
				ll m = (lv + rv) / 2;
				if(ok(res * 10 + m * 10)) rv = m;
				else lv = m;
			}
			cout << "! " << res + rv << endl;
			return;
		}
	}
}

