        cin >> res;
        if(res == 'Y') {
            yes = mid;
        } else {
            no = mid;
        }
    }

    while(yes % 10L == 0) {
        yes /= 10L;
    }

    while(true) {
        cout << "? " << yes+1L << endl;
        char res;
        cin >> res;
        if(res == 'Y') {
            cout << "! " << yes << endl;
            break;
        } else {
            yes *= 10L;
        }
    }
    return 0;
}

