string toString(const long long& x) {
  long long temp = x;
  string ret = "";
  while (temp) {
    ret = (char)('0' + temp % 10) + ret;
    temp /= 10;
  }
  return ret;
}

void check(const long long& x, char& ret) {
  string s = toString(x);
  cout << x << " " << s << endl;
  if (x <= ANS && s <= SANS)
    ret = 'Y';
  else if (x > ANS && s > SANS)
    ret = 'Y';
  else
    ret = 'N';
}

