void search(LL base) {
    LL left = base + 1;
    LL right = base * 10 - 1;
    while (left < right) {
        LL mid = (left+right+1) >> 1;
        mid *= 10;
        cout << "? " << mid << endl;
        string s;
        cin >> s;
        if (s == "Y") {
            right = mid / 10 - 1;
        }
        else {
            left = mid / 10;
        }
    }
    cout << "! " << left << endl;
}

