            else l = mid;
        }
        if (r != 9){
            isnine = false;
            if (ask((query + (r+1) * po(i+1)) / po(i+1))) {
                if (ask((query + r * po(i+1)) / po(i))) answer((query + r * po(i+1)) / po(i+1));
