int chpref(int N) {
	while (N <= 1e17) {
		N = 10 * N + 9;
	}
	return query(N);
}

void run() {
	int pr = 0;
	for (int j = 0; j < 20; j++) {
		if (j > 0 && chpref(10 * pr + 0)) {
			if (query(pr + 1) == chpref(pr + 1)) break;
