		}
		int l = 0;
		if (j > 0) l = -1;
		int r = 9;
		while (r - l > 1) {
			int m = (r + l) / 2;
			if (!chpref(10 * pr + m)) l = m;
			else r = m;
		}
		pr = 10 * pr + r;
	}
	#ifdef LOCAL
	if (n != pr) {
