	private void solveD() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long[] edges = new long[N - 1];
		for (int i = 1; i < N; i++) {
			long a = sc.nextLong();
			long b = sc.nextLong();
			long small = a < b ? a : b;
			long large = a > b ? a : b;
			edges[i - 1] = small * (N + 1) + large;
		}
		Arrays.sort(edges);
		int[] parents = new int[N + 1];

		parents[1] = -1;
		for (long edge : edges) {
			int small = (int)(edge / (N + 1));
			int large = (int)(edge % (N + 1));
			if (parents[large] == 0) {
				parents[large] = small;
			} else if (parents[small] == 0) {
				parents[small] = large;
			} else {
				System.err.println("Unexpected.");
			}
		}
		int depth_n = 0;
		{
			int p = N;
			while (parents[p] != -1) {
				depth_n++;
				p = parents[p];
			}
		}
		int[] team = new int[N + 1];
		{
			int depth = depth_n;
			int p = N;
			team[N] = N;
			while (parents[p] != -1) {
				depth--;
				p = parents[p];
				if (depth <= depth_n / 2) {
					team[p] = 1;
				} else {
					team[p] = N;
				}
			}
		}
		for (int i = 1; i <= N; i++) {
			Set<Integer> set = new HashSet<>();
			int p = i;
			while (team[p] == 0) {
				set.add(p);
				p = parents[p];
			}
			for (int q : set) {
				team[q] = team[p];
			}
		}
		int black = 0;
		int white = 0;
		for (int i = 1; i <= N; i++) {
			if (team[i] == 1) {
				black++;
			} else if (team[i] == N) {
				white++;
			}
		}
		System.out.println(black > white ? "Fennec" : "Snuke");
	}

