	static class TaskE {
		FastScanner in;
		PrintWriter out;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			this.in = in;
			this.out = out;
			String prefix = "";
			while (true) {
				int l = 0;
				int r = 10;
				if (prefix.isEmpty()) {
					l = 1;
				}
				while (r - l > 1) {
					int m = (l + r) / 2;
					if (send(prefix + m)) {
						l = m;
					} else {
						r = m;
					}
				}
				if (send(prefix + l)) {
					prefix += l;
				} else {
					break;
				}
			}
			out.println("! " + prefix);
			out.flush();
		}

		private boolean send(String s) {
			out.println("? " + s);
			out.flush();
			return in.next().equals("Y");
		}

	}

