class Solver {
  final Scanner scanner;

  Solver() {
    scanner = new Scanner(System.in);
  }

  private void writeBoth(String line) {
  }

  private boolean writeAndRead(long v) {
    String outputLine = String.format("? %d", v);
    System.err.println("Out: " + outputLine);
    System.out.println(outputLine);

    String inputLine = scanner.next();
    System.err.println("In:  " + inputLine);
    char c = inputLine.charAt(0);
    return c == 'Y';
  }

  private boolean isAllNine(long n) {
    while (n > 0) {
      if (n % 10 != 9) {
        return false;
      }
      n /= 10;
    }
    return true;
  }

  public void solve() {
    long candidateMin = 10_000_000_000L;
    long candidateMax = 99_999_999_999L;
    while (candidateMax - candidateMin >= 2) {
      long candidateMid = (candidateMax + candidateMin) / 2;
      if (writeAndRead(candidateMid)) {
        candidateMax = candidateMid;
      } else {
        candidateMin = candidateMid;
      }
    }
    long candidate = candidateMax / 10;
    while (candidate % 10 == 0) {
      long query = (candidate / 10) + 1;
      if (!writeAndRead(query)) {
        break;
      }
      candidate /= 10;
    }
    long answer;
    if (isAllNine(candidate)) {
      answer = candidate * 10;
    } else if (candidate % 10 == 0 && isAllNine(candidate / 10)) {
      answer = candidate / 10;
    } else {
      answer = candidate;
    }

    String line = String.format("! %d", answer);
    System.err.println("Out: " + line);
    System.out.println(line);
  }
}

public class Main {
  public static void main(String[] args) {
    new Solver().solve();
  }
}

