		}

public void solve() {
	int digit = 0;
	if(ask(pow(10, 12))) {
		for(int i = 0; i <= 10; i ++) {
			boolean ok = ask(pow(10, i)) && ask(pow(10, i + 1) - 1);
			if(ok) { digit = i + 1; break; }
		}
	}else {
		for(int i = 10; i >= 0; i --) {
			boolean ok = ask(pow(10, i)) && ask(pow(10, i + 1) - 1);
			if(ok) { digit = i + 1; break; }
		}
	}

	long ans = bisect(pow(10, digit) - 1, pow(10, digit - 1) - 1);
	prt("! ");
	prtln(ans);
}

