boolean ask(long x) {
	cnt ++;
	if(cnt > 64) { while(true) {  } }
	prt("? ");
	prtln(x);
	flush();
	return ns().equals("Y");
}

long bisect(long ok, long ng) {
	while (Math.abs(ok - ng) > 1) {
		// errprtln(ok, ng);
		long mid = (ok + ng) / 2;
		if(ask(mid * 10)) {
			ok = mid;
		}else {
			ng = mid;
		}
	}
	return ok;
}

