	for(int i = 0; i <= 9; i ++) {
		boolean ok = ask(pow(10, i)) && ask(pow(10, i + 1) - 1);
		if(ok) { digit = i + 1; break; }
	}
	long ans = bisect(pow(10, digit + 1) - 1, pow(10, digit)) / 10;
	prt("! ");
	prtln(ans);
}

