long bisect(long ok, long ng) {
	while (Math.abs(ok - ng) > 1) {
		long mid = (ok + ng) / 2;
		if(ask(mid)) {
			ok = mid;
		}else {
			ng = mid;
		}
	}
	return ok;
}

