import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    static InputReader in;
    static PrintWriter out;

    public static void main(String[] args) {
        in = new InputReader(System.in);
        out = new PrintWriter(System.out);
        out.println("! " + doit());
        out.flush();

        debug(Q);
    }

    static long power10() {
        long base = 1;
        long q = 9;
        while (!query(q)) {
            q *= 10;
            q += 9;
            base *= 10;
        }
        return base;
    }

    static long doit() {
        long base = 1;
        while (query(base)) {
            base *= 10;
            if (base >= 1e11) {
                return power10();
            }
        }
        long K = base / 10;

        long geta = 999999999_999999999L;
        int dec = 17;

        long who = 0;
        for (long k = K ; k >= 1 ; k /= 10) {
            long B = (long)Math.pow(10, dec);
            long min = (k == K) ? 0 : -1;
            long max = 9;
            while (max - min > 1) {
                long med = (max + min) / 2;
                long Q = geta - 9 * B + med * B;
                if (query(Q)) {
                    max = med;
                } else {
                    min = med;
                }
            }
            geta -= 9 * B;
            geta += max * B;
            who *= 10;
            who += max;
            dec--;
        }
        return who;
    }

    static long N;
    static long Q;

    public static boolean query(long n) {
        Q++;
//        if (true) {
//            return response(n);
//        }
        out.println("? " + n);
        out.flush();
        return in.nextToken().equals("Y");
    }

    public static boolean response(long n) {
        if (n <= N && String.valueOf(n).compareTo(String.valueOf(N)) <= 0) {
            return true;
        }
        if (n > N && String.valueOf(n).compareTo(String.valueOf(N)) > 0) {
            return true;
        }
        return false;
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedHashMap;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		ConsoleScanner cin = new ConsoleScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(ConsoleScanner cin, PrintWriter cout) {
		// example();

		// 二分法
		// ただし初期のleft, rightがわかりにくい

		long l = 10;
		for (; l <= (long) 1e10; l *= 10) {
			cout.println("? " + l);
			cout.flush();
			String ans = cin.next();
			if ("N".equals(ans))
				break;
		}
		if (l == (long) 1e11) {
			// every answer is Y if N = 1
			cout.println("! 1");
			return;
		}
		long r = l * 10 - 1;
		while (r - l >= 10) {
			long m = (l + r) / 2;
			cout.println("? " + m);
			cout.flush();
			String ans = cin.next();
			switch (ans) {
			case "Y":
				r = m;
				break;
			case "N":
				l = m;
				break;
			default:
				throw new IllegalStateException();
			}
		}
		long N = r / 10;
		cout.println("! " + N);
	}

	static void example() {
		// Nより小さい桁ではYYY...NNN
		// Nより同じ桁では全てY
		// Nより大きい桁ではNNN...YYY

		// N=50とN=51の差は？
		// ? 500 ~ ? 509の回答がY/Nになる
		for (int N : new int[] { 1, 7, 9, 10, 50, 51, 99 }) {
			String strN = Integer.toString(N);
			LinkedHashMap<Integer, Character> map = new LinkedHashMap<>();
			for (int n = 1; n <= 1000; n++) {
				String strn = Integer.toString(n);
				Character ans;
				if (n >= N && strn.compareTo(strN) >= 0)
					ans = 'Y';
				else if (n < N && strn.compareTo(strN) < 0)
					ans = 'Y';
				else
					ans = 'N';
				map.put(n, ans);
			}
			System.out.println(map);
		}

	}

	static class ConsoleScanner {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		String next() {
			try {
				while (!st.hasMoreElements())
					st = new StringTokenizer(br.readLine());
				return st.nextToken();
			} catch (IOException e) {
				throw new AssertionError(e);
			}
		}

		int nextInt() {
			return Integer.parseInt(next());
		}
	}

}

import java.util.Scanner;

public class Main {
    public static void main(String [] args) {
        long max = 1000000000L;
        Scanner scanner = new Scanner(System.in);
        System.out.println("? " + max);
        String ans = scanner.next();
        if (ans.equals("Y")) {
            System.out.println("! " + max);
            return;
        }
        int length = 1;
        long i;

        for (i = 999999999L; i > 0; i/= 10) {
            System.out.println("? " + i);
            ans = scanner.next();
            if (ans.equals("N")) {
                length = getLength(i) + 1;
                break;
            }
        }
        int[] num = new int[length + 1];
        for (int k = 0; k < length + 1; ++k) {
            num[k] = 9;
        }
        for (int pos = 0; pos < length; ++pos) {
            findValueOnCurrentPos(num, pos, scanner);
        }
        System.out.print("! ");

        for (int pos = 0; pos < length; ++pos) {
            System.out.print(num[pos]);
        }
        System.out.println();

    }

    public static void findValueOnCurrentPos(int[] num, int pos, Scanner scanner) {
        String ans;
        int l = -1; // value > l
        int r = 10; // value <= r
        while (r - l > 1) {
            int mid = (l + r) / 2;
            num[pos] = mid;
            System.out.print("? ");
            for (int i = 0; i < num.length; ++i) {
                System.out.print(num[i]);
            }
            System.out.println();
            ans = scanner.next();
            if (ans.equals("Y")) {
                r = mid;
            } else {
                l = mid;
            }
        }

        num[pos] = r;
    }

    public static int getLength(long i) {
        int length = 0;
        while (i > 0) {
            ++length;
            i /= 10;
        }
        return length;
    }
}

