class FastScanner {
  public static String debug = null;

  private final InputStream in = System.in;
  private int ptr = 0;
  private int buflen = 0;
  private byte[] buffer = new byte[1024];
  private boolean eos = false;

  private boolean hasNextByte() {
    if (ptr < buflen) {
      return true;
    } else {
      ptr = 0;
      try {
        if (debug != null) {
          buflen = debug.length();
          buffer = debug.getBytes();
          debug = "";
          eos = true;
        } else {
          buflen = in.read(buffer);
        }
      } catch (IOException e) {
        e.printStackTrace();
      }
      if (buflen < 0) {
        eos = true;
        return false;
      } else if (buflen == 0) {
        return false;
      }
    }
    return true;
  }

  private int readByte() {
    if (hasNextByte())
      return buffer[ptr++];
    else
      return -1;
  }

  private static boolean isPrintableChar(int c) {
    return 33 <= c && c <= 126;
  }

  private void skipUnprintable() {
    while (hasNextByte() && !isPrintableChar(buffer[ptr]))
      ptr++;
  }

  public boolean isEOS() {
    return this.eos;
  }

  public boolean hasNext() {
    skipUnprintable();
    return hasNextByte();
  }

  public String next() {
    if (!hasNext())
      throw new NoSuchElementException();
    StringBuilder sb = new StringBuilder();
    int b = readByte();
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b);
      b = readByte();
    }
    return sb.toString();
  }

  public long nextLong() {
    if (!hasNext())
      throw new NoSuchElementException();
    long n = 0;
    boolean minus = false;
    int b = readByte();
    if (b == '-') {
      minus = true;
      b = readByte();
    }
    if (b < '0' || '9' < b) {
      throw new NumberFormatException();
    }
    while (true) {
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      b = readByte();
    }
  }

  public int nextInt() {
    return (int) nextLong();
  }

  public long[] nextLongList(int n) {
    return nextLongTable(1, n)[0];
  }

  public int[] nextIntList(int n) {
    return nextIntTable(1, n)[0];
  }

  public long[][] nextLongTable(int n, int m) {
    long[][] ret = new long[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextLong();
      }
    }
    return ret;
  }

  public int[][] nextIntTable(int n, int m) {
    int[][] ret = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextInt();
      }
    }
    return ret;
  }
}

import java.util.Scanner;

public class Main{
  static final long n = 10;

  static final boolean DEBUG = false;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    StringBuilder left = new StringBuilder("1");
    StringBuilder right = new StringBuilder("10");
    boolean foundLength = false;
    int length = 1;
    while(true){
      System.out.println("? " + left);
      System.out.flush();
      //boolean ans1 = question(Long.decode(left.toString()));
      boolean ans1 = sc.next().equals("Y");
      assert ans1 == question(Long.decode(left.toString()));
      System.out.println("? " + right);
      System.out.flush();
      boolean ans2 = sc.next().equals("Y");
      assert ans2 == question(Long.decode(right.toString()));
      //boolean ans2 = question(Long.decode(right.toString()));
      if(ans1 && !ans2){
        foundLength = true;
        break;
      }
      if(length >= 10){
        break;
      }
      length++;
      left.append("0");
      right.append("0");
    }

    if(DEBUG){
      System.out.println("length = " + length);
    }

    if(foundLength){
      if(DEBUG){
        System.out.println("left = " + left);
        System.out.println("right = " + right);
      }
      long low = 1;
      for(int i = 0; i < length - 1; i++){
        low *= 10;
      }
      long high = 1;
      for(int i = 0; i < length; i++){
        high *= 10;
      }
      high--;
      if(DEBUG){
        System.out.println("low = " + low);
        System.out.println("high = " + high);
      }
      while(high - low > 1){
        long mid = (low + high) / 2;
        System.out.println("? " + (mid * 10L));
        System.out.flush();
        //boolean ans = question(mid * 10);
        boolean ans = sc.next().equals("Y");
        assert ans == question(mid * 10L);
        if(DEBUG){
          System.out.println("mid = " + mid);
          System.out.println(ans);
        }
        if(ans){
          high = mid;
        }
        else{
          low = mid;
        }
      }
      System.out.println("! " + high);
    }
    else{
      // 1, 100, 1000, 10000
      long v = 10;
      while(v <= 1000000000){
        //boolean ans1 = question(v - 1);
        System.out.println("? " + (v - 1));
        System.out.flush();
        boolean ans1 = sc.next().equals("Y");
        assert ans1 == question(v - 1);
        //boolean ans2 = question(v + 1);
        System.out.println("? " + (v + 1));
        System.out.flush();
        boolean ans2 = sc.next().equals("Y");
        assert ans2 == question(v + 1);
        if(!ans1 && ans2){
          System.out.println("! " + v);
          return;
        }
        v *= 10L;
      }
      System.out.println("! " + 1);
    }
  }

  private static boolean question(long x){
    return (x <= n && Long.toString(x).compareTo(Long.toString(n)) <= 0) ||
      (x > n && Long.toString(x).compareTo(Long.toString(n)) > 0);
  }
}

