					if(pln(ans * 10 + 3)){
						if(pln(ans * 10 + 4)){
							ans = ans * 10 + 4;
						}else{
							ans = ans * 10 + 3;
						}
					}else{
						if(pln(ans * 10 + 2)){
							ans = ans * 10 + 2;
						}else{
							ans = ans * 10 + 1;
						}
					}
				}
			}

			if(!pln(ans * 100 + 40)){
				if(!pln(ans * 100 + 60)){
					if(!pln(ans * 100 + 70)){
						if(!pln(ans * 100 + 80)){
							ans = ans * 10 + 9;
						}else{
							ans = ans * 10 + 8;
						}
					}else{
						ans = ans * 10 + 7;
					}
				}else{
					if(!pln(ans * 100 + 50)){
						ans = ans * 10 + 6;
					}else{
						ans = ans * 10 + 5;
					}
				}
			}else{
				if(!pln(ans * 100 + 20)){
					if(!pln(ans * 100 + 30)){
						ans = ans * 10 + 4;
					}else{
						ans = ans * 10 + 3;
					}
				}else{
					if(!pln(ans * 100 + 10)){
						ans = ans * 10 + 2;
					}else{
						ans = ans * 10 + 1;
					}
				}
			}
			System.out.println("! " + ans);
		}

	}

	public static void main(String[] args){
		new Main().solve();
	}
}

