public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    long candidateMin = 10_000_000_000L;
    long candidateMax = 99_999_999_999L;
    while (candidateMax - candidateMin >= 2) {
      long candidateMid = (candidateMax + candidateMin) / 2;
      out.printf("? %d\n", candidateMid);
      out.flush();
      char c = reader.next().charAt(0);
      if (c == 'Y') {
        candidateMax = candidateMid;
      } else {
        candidateMin = candidateMid;
      }
    }
    long candidate = candidateMax / 10;
    while (true) {
      long query = (candidate / 10) + 1;
      out.printf("? %d\n", query);
      out.flush();
      char c = reader.next().charAt(0);
      if (c == 'N') {
        out.printf("! %d\n", candidate);
        return;
      }
      candidate /= 10;
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

