				if(!pln(ans * 100 + 20)){
					if(!pln(ans * 100 + 30)){
						ans = ans * 10 + 4;
					}else{
						ans = ans * 10 + 3;
					}
				}else{
					if(!pln(ans * 100 + 10)){
						ans = ans * 10 + 2;
					}else{
						ans = ans * 10 + 1;
					}
				}
			}
			System.out.println("! " + ans);
		}

	}

	public static void main(String[] args){
		new Main().solve();
	}
}

