		}else{
			for(int i = 9;i >= 1;i--){
				if(!q(Long.parseLong(nine.substring(0, i)))){
					out.println("! " + Long.toString(high).substring(0, i+1));
					out.flush();
					return;
				}
			}
			out.println("! " + Long.toString(high).substring(0, 1));
			out.flush();
		}
	}

