 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskE solver = new TaskE();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskE {
		FastScanner in;
		PrintWriter out;
		boolean LOCAL_RUN = false;
		final String N = "998922";

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			this.in = in;
			this.out = out;
			String prefix = "";
			while (true) {
				int l = 0;
				int r = 10;
				if (prefix.isEmpty()) {
					l = 1;
				}
				while (r - l > 1) {
					int m = (l + r) / 2;
					if (!send(prefix + m + "000000000")) {
						l = m;
					} else {
						r = m;
					}
				}
				if (send(prefix + l) == send(prefix + l + "000000000")) {
					break;
				}
				if (!send(prefix + l + "000000000")) {
					prefix += l;
				} else {
					break;
				}
			}
			if (prefix.isEmpty()) {
				prefix = "0";
			}
			long ans = Long.parseLong(prefix) + 1;

			out.println("! " + ans);
			out.flush();
		}

		private boolean send(String s) {
			if (zero(s)) {
				return true;
			}
			if (LOCAL_RUN) {
				boolean u = Long.parseLong(s) <= Long.parseLong(N);
				boolean v = s.compareTo(N) <= 0;
				boolean res = (u && v) || (!u && !v);
//			System.out.println(s + " " + res);
				return res;
			}
			out.println("? " + s);
			out.flush();
			return in.next().equals("Y");
		}

		private boolean zero(String s) {
			for (char c : s.toCharArray()) {
				if (c != '0') {
					return false;
				}
			}
			return true;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws Exception{
		Scanner scan = new Scanner(System.in);
		Main main = new Main();
		// 桁数
		int l;
		// 答え
		int N = 0;

		for(l = 1; l < 10;l++) {
			main.output(false, (int)Math.pow(10,l));
			if(main.input(scan) == 0) {
				break;
			}
		}

		if(l != 10) {
			int nMin = (int)Math.pow(10, l - 1);
			int nMax = (int)Math.pow(10, l) - 1;

			while(nMin != nMax) {
				int n = (nMin + nMax) / 2;
				main.output(false, n);
				if(main.input(scan) == 0) {
					nMin = n + 1;
				} else {
					nMax = n;
				}
			}
			N = nMin;
		} else {
			for(l = 0; l < 10;l++) {
				main.output(false, (int)Math.pow(10,l) * 2);
				if(main.input(scan) == 1) {
					N = (int)Math.pow(10,l);
					break;
				}
			}
		}
		main.output(true, N);
	}

	private void output(boolean answerFlag,int n) {
		if(answerFlag) {
			System.out.println("! " + n);
		} else {
			System.out.println("? " + n);
		}
		System.out.flush();
	}

	private int input(Scanner scan) throws Exception {
		if(scan.next() == "Y") {
			return 1;
		} else
		if(scan.next() == "N") {
			return 0;
		} else {
			throw new Exception();
		}
	}
}

