/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskE solver = new TaskE();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskE {
		FastScanner in;
		PrintWriter out;
		boolean LOCAL_RUN = false;
		final String N = "1000";
		Map<String, Boolean> cache = new HashMap<>();

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			this.in = in;
			this.out = out;
			String prefix = "";
			String zeros = "000000000";
			while (true) {
				int l = 0;
				int r = 10;
				if (prefix.isEmpty()) {
					l = 1;
				}
				while (r - l > 1) {
					int m = (l + r) / 2;
					if (!send(prefix + m + zeros)) {
						l = m;
					} else {
						r = m;
					}
				}
				if (send(prefix + l) == send(prefix + l + zeros)) {
					break;
				}
				if (!send(prefix + l + zeros)) {
					prefix += l;
				} else {
					break;
				}
			}
			if (prefix.isEmpty()) {
				prefix = "0";
			}
			long ans = Long.parseLong(prefix) + 1;
			if (ans == 1) {
				while (!send("" + (ans + 1))) {
					ans *= 10;
				}
			}

			out.println("! " + ans);
			out.flush();
		}

		private boolean send(String s) {
			if (cache.containsKey(s)) {
				return cache.get(s);
			}
			if (zero(s)) {
				return true;
			}
			if (LOCAL_RUN) {
				boolean u = Long.parseLong(s) <= Long.parseLong(N);
				boolean v = s.compareTo(N) <= 0;
				boolean res = (u && v) || (!u && !v);
				System.out.println(s + " " + res);
				return res;
			}
			out.println("? " + s);
			out.flush();
			boolean res = in.next().equals("Y");
			cache.put(s, res);
			return res;
		}

		private boolean zero(String s) {
			for (char c : s.toCharArray()) {
				if (c != '0') {
					return false;
				}
			}
			return true;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

	}
}

