	void solve() throws IOException {
//		debug();
//		N = 10;// for debug
		// 1桁かどうか特定する
		long ans = !next(10) ? oneDig() : sumDig();
		out.println("! " + ans);
		out.flush();
	}

	void debug() throws IOException {
		for(int i = 1; i <= 100000; i++) {
			N = i;
//			System.out.println("test: " + i);
			long ans = !next(10) ? oneDig() : sumDig();
//			out.println("! " + ans);
//			out.flush();
			if(ans != N) {
				System.err.println(N);
			}
		}
	}

	long inf = 1000000000;
	long sumDig() {
		// 1の可能性があることに注意
		long top = -1;
		for(int i = 1; i <= 9; i++) {
			if(!next(i)) {
				top = i - 1;
				break;
			}
		}
		if(top == -1) top = 9;
		int topD = (int) top;
		// 桁を特定
		for(int i = 0; i < 10; i++) {
			if(!next(top * 10)) break;
			top *= 10;
		}
		if(top > inf) {
			top = tail0(topD);
			if(top == 1) return 1;
		}

		long left = top;
		long right = left + (long)Math.pow(10, (int)Math.log10(left)) - 1;
		long ans = 0;
//		System.out.println(left + " " + right);
		while(left <= right) {
			long mid = (left + right) / 2;
			if(!next(mid * 10)) {
				ans = mid;
				left = mid + 1;
			} else {
				right = mid - 1;
			}
		}
		if(ans == 0) ans = top;
		else ans++;
		return ans;
	}

	long tail0(long top) {
		if(top == 9) {
			for(int i = 0; i < 10; i++) {
				top *= 10;
				if(!next(top - 1)) break;
			}
			if(top > inf) return 1;
			return top / 10;
		} else {
			long oldTop = top;
			top++;
			for(int i = 0; i < 10; i++) {
				if(next(top * 10)) break;
				top *= 10;
				oldTop *= 10;
			}
			return oldTop * 10;
		}
	}

	int oneDig() {
		// 2 - 9 の整数
		int top = -1;
		for(int i = 1; i <= 9; i++) {
			if(next(i * 10)) {
				top = i;
				break;
			}
		}
		return top;
	}

	int N = -1;
	boolean next(long n) {
		if(N > 0) {
			if(n <= N && Long.toString(n).compareTo("" + N) <= 0
					|| n > N && Long.toString(n).compareTo("" + N) > 0) return true;
			return false;
		}
		try {
			out.println("? " + n);
			out.flush();
			boolean ans = in.nextToken().equals("Y");
			return ans;
		} catch(IOException e) {
			e.printStackTrace();
		}
		return false;
	}
}

