public void solve() {
	int digit = 0;
	for(int i = 0; i <= 10; i ++) {
		boolean ok = ask(pow(10, i)) && ask(pow(10, i + 1) - 1);
		if(ok) { digit = i + 1; break; }
	}
	long ans = bisect(pow(10, digit + 1) - 1, pow(10, digit)) / 10;
	prt("! ");
	prtln(ans);
}

boolean ask(long x) {
	prt("? ");
	prtln(x);
	flush();
	return ns().equals("Y");
}

long bisect(long ok, long ng) {
	while (Math.abs(ok - ng) > 1) {
		long mid = (ok + ng) / 2 / 10 * 10;
		if(ask(mid)) {
			ok = mid;
		}else {
			ng = mid;
		}
	}
	return ok;
}

