    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func Join(A []int) string {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  return strings.Join(S, "")
}

func Query(A []int) bool {
  Write("? " + Join(A))
  Output()
  ans := NextLine()
  return ans == "Y"
}

func Solve() {
  A := make([]int, 10)
  A[0] = 1
  if Query(A) {
    Write("! " + Join(A))
    return
  }
  le, gt := 1, 10
  for 1 < gt - le {
    med := (gt + le) / 2
    if Query(A[:med]) {
      le = med
    } else {
      gt = med
    }
  }
  A = A[:gt]
  for i := range A[1:] {
    le, gt := A[i], 9
    A[i] = 9
    if !Query(A) { A[i - 1]++ }
    A[i] = le
    if Query(A) { continue }
    for 1 < gt - le {
      A[i] = (gt + le) / 2
      if Query(A) {
        gt = A[i]
      } else {
        le = A[i]
      }
    }
    A[i] = le
    if i == len(A) - 2 { A[i]++ }
  }
  Write("! " + Join(A[:len(A) - 1]))
  Output()
}

