func configure(scanner *bufio.Scanner) {
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1000005), 1000005)
}
func getNextString(scanner *bufio.Scanner) string {
	scanned := scanner.Scan()
	if !scanned {
		panic("scan failed")
	}
	return scanner.Text()
}
func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}
func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}
func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}
func main() {
	fp := os.Stdin
	wfp := os.Stdout
	extra := 0
	if os.Getenv("I") == "IronMan" {
		fp, _ = os.Open(os.Getenv("END_GAME"))
		extra = 0
	}
	scanner := bufio.NewScanner(fp)
	configure(scanner)
	writer := bufio.NewWriter(wfp)
	defer func() {
		r := recover()
		if r != nil {
			fmt.Fprintln(writer, r)
		}
		writer.Flush()
	}()
	solve(scanner, writer)
	for i := 0; i < extra; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	var ans int64
	for i := 0; i < 10; i++ {
		ans *= 10
		l := -1
		r := 10
		for l+1 < r {
			m := (l + r) >> 1
			if ans+int64(m) == 0 {
				r = 1
				break
			}
			if (ans+int64(m))*1000000000+999999999 < 0 {
				ans -= int64(r)
				break
			}
			res := ask((ans+int64(m))*1000000000+999999999, scanner, writer)
			if res == "Y" {
				r = m
				continue
			}
			l = m
		}
		ans += int64(r)
	}
	if pow10(ans) {
		for ans > 0 {
			res := ask(ans/10+1, scanner, writer)
			if res == "N" {
				fmt.Fprintln(writer, fmt.Sprintf("! %d", ans))
				return
			}
			ans /= 10
		}
		return
	}
	for ans > 0 {
		res := ask(ans-1, scanner, writer)
		if res == "Y" {
			fmt.Fprintln(writer, fmt.Sprintf("! %d", ans))
			return
		}
		ans /= 10
	}
}

func pow10(x int64) bool {
	for x%10 == 0 {
		x /= 10
	}
	return x == 1
}
func ask(n int64, scanner *bufio.Scanner, writer *bufio.Writer) string {
	fmt.Fprintln(writer, fmt.Sprintf("? %d", n))
	writer.Flush()
	return getNextString(scanner)
}

