    print('?', n)
    ans = input().rstrip()
    return ans == 'Y'

def solve():
    if ask(10**10):
        # power of 10
        for n in range(10,-1,-1):
            if not ask(10 ** n):
                return 10 ** (n+1)
        return 1
    # 以下10のべき乗以外
    digit = 10
    while not ask(10 ** digit):
        # 10 のべきを投げると、辞書順では自動で勝つ
        # よって、NO = n\leq 10^digit
        digit -= 1
    digit += 1
    # Nはd桁
    left = 10 ** (d-1) # Nより小さい
    right = 10 ** d - 1 # N以上
    while right > left + 1:
        mid = (left + right) // 2
        if ask(mid * 10 ** 9):
            # 数字順では勝つ
            # 辞書順でmid >= NのときにTrue
            right = mid
        else:
            left = mid
    return mid

