const ANSWER: i64 = 123456700;
const SIMULATE: bool = false;

fn query(v: i64) -> bool {
    println!("? {}", v);
    std::io::stdout().flush().unwrap();
    if SIMULATE {
        (ANSWER <= v && ANSWER.to_string() <= v.to_string())
            || (ANSWER > v && ANSWER.to_string() > v.to_string())
    } else {
        read::<String>() == "Y"
    }
}

fn answer(v: i64) {
    if SIMULATE {
        println!("! {} {}", ANSWER, v);
        assert!(ANSWER == v);
    } else {
        println!("! {}", v);
        std::io::stdout().flush().unwrap();
    }
}

fn main() {
    let mut digits = vec![];
    for i in 0..10 {
        let mut left = if i == 0 { 0 } else { -1 };
        let mut right = 9;
        while right - left > 1 {
            let mut mid = (left + right) / 2;
            let mut v = 0;
            for d in digits.iter() {
                v = v * 10 + d;
            }
            v = v * 10 + mid;
            while v < 1e+9 as i64 {
                v = v * 10 + 9;
            }
            if query(v) {
                right = mid;
            } else {
                left = mid;
            }
        }
        digits.push(right);
    }
    while *digits.last().unwrap() == 0 {
        let mut v = 0;
        if digits.iter().filter(|&&v| v != 0).all(|&v| v == 9) {
            v = 1;
            for i in 0..digits.len() - 1 {
                v *= 10;
            }
            if query(v) {
                break;
            } else {
                digits.pop();
            }
        } else {
            for i in 0..digits.len() - 1 {
                v = v * 10 + 9;
            }
            if query(v) {
                digits.pop();
            } else {
                break;
            }
        }
    }
    let mut ans = 0;
    for d in digits.iter() {
        ans = ans * 10 + d;
    }
    answer(ans);
}

