use std::io;
use std::io::prelude::*;

fn ask(n: String) -> bool {
    let mut stdout = io::stdout();
    stdout.write(format!("? {}", n).as_bytes());
    stdout.flush();
    let mut stdin = io::stdin();
    let mut input = String::new();
    stdin.read_line(&mut input);
    input.starts_with("Y")
}

fn is_last(s: &str) -> bool {
    if s.starts_with("9") {
        let mut t = String::new();
        t += "1";
        for _ in 0..s.len()+1 {
            t += "0";
        }
        !ask(t)
    } else {
        let mut t = String::new();
        for _ in 0..s.len()+1 {
            t += "9";
        }
        ask(t)
