fn is_last(s: &str) -> bool {
    if s.starts_with("1") || (s.len() == 0 && ask("1000000000000".to_string())) {
        let mut t = String::new();
        for _ in 0..s.len()+1 {
            t += "9";
        }
        ask(t)
    } else {
        let mut t = String::new();
        t += "1";
        for _ in 0..s.len()+1 {
            t += "0";
        }
        !ask(t)
    }
}
