fn answer(n: u64) {
    println!("! {}", n);
}


fn main() {
    let mut sc = Scanner::new(std::io::stdin());

    if favorite(&mut sc, 10_000_000_000) {
        let mut ans = 1;
        loop {
            if favorite(&mut sc, ans * 2) {
                answer(ans);
                return;
            }
            ans *= 10;
        }
    }

    let mut dig = 1;
    let mut ten = 1;
    loop {
        if !favorite(&mut sc, ten * 10) {
            break;
        }
        ten *= 10;
        dig += 1;
    }

    let mut head = 0;
    for i in 0..dig {
        let mut left: i32 = -1;
        let mut right: i32 = 10;
        while right - left > 1 {
            let mid = (left + right) / 2;
            if favorite(&mut sc,
                        (head * 10 + mid as u64) * (if i + 1 == dig { 10 } else { 1 })) {
                if i + 1 < dig {
                    left = mid;
                } else {
                    right = mid;
                }
            } else {
                if i + 1 < dig {
                    right = mid;
                } else {
                    left = mid;
                }
            }
        }
        head = head * 10 + left as u64;
    }
    answer(head + 1);
}

